:root {
  --ink: #0a1322;
  --ink-2: #111f34;
  --panel: rgba(13, 24, 41, 0.92);
  --line: rgba(150, 190, 255, 0.18);
  --gold: #ffc63d;
  --gold-2: #f0a91f;
  --blue: #4aa7ff;
  --red: #ff5f70;
  --text: #f4f8ff;
  --muted: #9db1cb;
  --font: "Avenir Next", "Segoe UI", system-ui, -apple-system, "Helvetica Neue", Arial, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  height: 100%;
  margin: 0;
}

body {
  display: grid;
  place-items: center;
  overflow: hidden;
  background:
    radial-gradient(80% 60% at 50% 10%, #16283f 0%, transparent 60%),
    radial-gradient(70% 50% at 50% 100%, #0c1a2c 0%, transparent 65%),
    #060b14;
  color: var(--text);
  font-family: var(--font);
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

#app {
  position: relative;
  width: min(100vw, calc(100dvh * 9 / 16));
  height: min(100dvh, calc(100vw * 16 / 9));
  overflow: hidden;
  background: #0a1322;
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.65), 0 0 0 1px rgba(120, 170, 255, 0.08);
}

@media (min-width: 720px) and (min-height: 820px) {
  #app { border-radius: 26px; }
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  cursor: default;
}

.overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: max(18px, env(safe-area-inset-top)) max(18px, env(safe-area-inset-right)) max(18px, env(safe-area-inset-bottom)) max(18px, env(safe-area-inset-left));
  background:
    radial-gradient(55% 45% at 50% 35%, rgba(29, 57, 91, 0.55), transparent 70%),
    rgba(5, 10, 18, 0.72);
  backdrop-filter: blur(7px);
  -webkit-backdrop-filter: blur(7px);
  z-index: 5;
}

.overlay.hidden { display: none; }

.panel {
  position: relative;
  width: min(100%, 430px);
  max-height: 100%;
  overflow-y: auto;
  padding: 30px 30px 24px;
  border: 1px solid var(--line);
  border-radius: 26px;
  background:
    linear-gradient(180deg, rgba(27, 48, 76, 0.55), transparent 38%),
    var(--panel);
  box-shadow: 0 26px 70px rgba(0, 0, 0, 0.55), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  text-align: center;
  pointer-events: auto;
  animation: panel-in 260ms cubic-bezier(0.2, 0.9, 0.25, 1) both;
}

@keyframes panel-in {
  from { opacity: 0; transform: translateY(14px) scale(0.97); }
  to { opacity: 1; transform: none; }
}

.hidden { display: none !important; }

.crest {
  width: 64px;
  height: 64px;
  margin: 0 auto 8px;
  filter: drop-shadow(0 8px 18px rgba(255, 186, 32, 0.3));
}

.crest svg { width: 100%; height: 100%; }

.logo {
  margin: 0;
  font-size: clamp(34px, 8vw, 48px);
  font-weight: 900;
  letter-spacing: 0.045em;
  line-height: 1;
  background: linear-gradient(180deg, #fff7dc 0%, #ffd463 48%, #e79b12 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  text-shadow: 0 8px 30px rgba(255, 180, 30, 0.18);
}

.logo span { color: transparent; }

.tagline {
  margin: 10px 0 22px;
  color: var(--muted);
  font-size: 14px;
  letter-spacing: 0.02em;
}

.difficulty {
  display: flex;
  gap: 6px;
  padding: 5px;
  margin: 0 auto 18px;
  width: max-content;
  max-width: 100%;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(5, 12, 22, 0.55);
}

.chip {
  border: 0;
  border-radius: 999px;
  padding: 9px 14px;
  background: transparent;
  color: var(--muted);
  font: 700 12px/1 var(--font);
  letter-spacing: 0.04em;
  cursor: pointer;
  transition: color 150ms, background 150ms, box-shadow 150ms;
}

.chip:hover { color: var(--text); }

.chip.selected {
  color: #2a1a00;
  background: linear-gradient(180deg, #ffe27d, var(--gold-2));
  box-shadow: 0 5px 16px rgba(240, 169, 31, 0.3);
}

.btn {
  display: block;
  width: 100%;
  border: 0;
  border-radius: 15px;
  padding: 15px 18px;
  font: 800 16px/1 var(--font);
  letter-spacing: 0.045em;
  cursor: pointer;
  transition: transform 120ms ease, filter 150ms ease, box-shadow 150ms ease;
}

.btn:active { transform: translateY(2px) scale(0.99); }
.btn:focus-visible { outline: 3px solid rgba(255, 214, 90, 0.75); outline-offset: 3px; }

.btn.primary {
  color: #2a1a00;
  background: linear-gradient(180deg, #ffe27d 0%, #ffc63d 45%, #eda51a 100%);
  box-shadow: 0 10px 30px rgba(255, 179, 26, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.55);
}

.btn.primary:hover { filter: brightness(1.05); }

.btn.ghost {
  margin-top: 10px;
  color: var(--text);
  background: rgba(255, 255, 255, 0.055);
  border: 1px solid var(--line);
}

.btn.ghost:hover { background: rgba(255, 255, 255, 0.1); }

.howto {
  margin-top: 22px;
  padding-top: 18px;
  border-top: 1px solid var(--line);
  text-align: left;
}

.howto-row {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  margin-bottom: 12px;
}

.howto-row:last-child { margin-bottom: 0; }

.key {
  flex: 0 0 23px;
  width: 23px;
  height: 23px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  background: rgba(255, 198, 61, 0.14);
  border: 1px solid rgba(255, 198, 61, 0.32);
  color: var(--gold);
  font: 800 11px/1 var(--font);
}

.howto p {
  margin: 2px 0 0;
  color: #c3d3e6;
  font-size: 12.5px;
  line-height: 1.45;
}

.footnote {
  margin: 16px 0 0;
  color: #7488a2;
  font-size: 10.5px;
  line-height: 1.45;
}

.eyebrow {
  margin: 0 0 6px;
  color: var(--gold);
  font: 800 11px/1 var(--font);
  letter-spacing: 0.22em;
}

.result-title {
  margin: 0;
  font-size: clamp(38px, 10vw, 52px);
  font-weight: 900;
  letter-spacing: 0.01em;
  line-height: 1;
  background: linear-gradient(180deg, #fff8e2, #ffd05a 55%, #e59c12);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.result-title.small { font-size: clamp(32px, 8vw, 42px); }

.result-title.lose {
  background: linear-gradient(180deg, #fff0f1, #ff8f9b 55%, #d93d4e);
  -webkit-background-clip: text;
  background-clip: text;
}

.result-title.draw {
  background: linear-gradient(180deg, #f2f7ff, #a9bfd9 55%, #68809e);
  -webkit-background-clip: text;
  background-clip: text;
}

.crown-row {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin: 18px 0 14px;
}

.crown-pip {
  width: 46px;
  height: 46px;
  display: grid;
  place-items: center;
  border-radius: 14px;
  border: 1px solid rgba(255, 198, 61, 0.22);
  background: rgba(255, 198, 61, 0.07);
  color: rgba(255, 198, 61, 0.22);
  font-size: 26px;
  line-height: 1;
}

.crown-pip.on {
  color: var(--gold);
  background: linear-gradient(180deg, rgba(255, 212, 99, 0.22), rgba(240, 169, 31, 0.1));
  border-color: rgba(255, 198, 61, 0.5);
  box-shadow: 0 6px 20px rgba(255, 180, 30, 0.16);
}

.end-sub {
  margin: 0 0 16px;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.5;
}

.stats {
  margin: 0 0 20px;
  border: 1px solid var(--line);
  border-radius: 14px;
  overflow: hidden;
}

.stat-row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 14px;
  background: rgba(255, 255, 255, 0.025);
  font-size: 12px;
}

.stat-row + .stat-row { border-top: 1px solid var(--line); }
.stat-row span:first-child { color: var(--muted); }
.stat-row span:last-child { color: var(--text); font-weight: 700; }

@media (max-height: 760px) {
  .panel { padding: 22px 24px 18px; }
  .tagline { margin-bottom: 15px; }
  .howto { margin-top: 16px; padding-top: 14px; }
  .howto-row { margin-bottom: 9px; }
  .crest { width: 50px; height: 50px; margin-bottom: 4px; }
}

@media (max-height: 640px) {
  .howto, .footnote { display: none; }
  .tagline { margin-bottom: 12px; }
  .difficulty { margin-bottom: 12px; }
  .panel { padding: 18px 22px; }
}

