export const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
export const lerp = (a, b, t) => a + (b - a) * t;
export const rand = (a, b) => a + Math.random() * (b - a);
export const randInt = (a, b) => Math.floor(rand(a, b + 1));
export const pick = (arr) => arr[(Math.random() * arr.length) | 0];
export const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
export const font = (size, weight = 800) =>
  `${weight} ${size}px "Avenir Next", "Segoe UI", system-ui, -apple-system, sans-serif`;

export function roundRectPath(c, x, y, w, h, r) {
  const rr = Math.min(r, w / 2, h / 2);
  c.beginPath();
  c.moveTo(x + rr, y);
  c.arcTo(x + w, y, x + w, y + h, rr);
  c.arcTo(x + w, y + h, x, y + h, rr);
  c.arcTo(x, y + h, x, y, rr);
  c.arcTo(x, y, x + w, y, rr);
  c.closePath();
}

export function fillRoundRect(c, x, y, w, h, r, fill) {
  roundRectPath(c, x, y, w, h, r);
  c.fillStyle = fill;
  c.fill();
}

export function shuffle(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = (Math.random() * (i + 1)) | 0;
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

export function makeDeck(elixir = 5) {
  const d = shuffle([...DECK]);
  return { hand: d.slice(0, 4), queue: d.slice(4), elixir };
}

export function formatTime(seconds) {
  const s = Math.max(0, Math.ceil(seconds));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
}

export function insideRect(px, py, r) {
  return px >= r.x && px <= r.x + r.w && py >= r.y && py <= r.y + r.h;
}

export function pointInArena(x, y, pad = 0) {
  return x >= ARENA.x + pad && x <= ARENA.right - pad && y >= ARENA.y + pad && y <= ARENA.bottom - pad;
}

export function unitHeight(r) {
  return r * 2.55;
}

/* Tiny WebAudio synth for game feedback — no assets, no dependencies. */

export class Sound {
  constructor() {
    this.ctx = null;
    this.enabled = true;
    try {
      const saved = localStorage.getItem('mini-clash-muted');
      if (saved === '1') this.enabled = false;
    } catch { /* storage can be unavailable */ }
  }

  init() {
    if (!this.ctx) {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return null;
      this.ctx = new AC();
    }
    if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
    return this.ctx;
  }

  toggle() {
    this.enabled = !this.enabled;
    try { localStorage.setItem('mini-clash-muted', this.enabled ? '0' : '1'); } catch { /* ignore */ }
    if (this.enabled) this.play('select');
    return this.enabled;
  }

  tone(freq, dur, type = 'sine', vol = 0.16, slideTo = null, delay = 0) {
    const c = this.init();
    if (!c) return;
    const t0 = c.currentTime + delay;
    const osc = c.createOscillator();
    const gain = c.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t0);
    if (slideTo) osc.frequency.exponentialRampToValueAtTime(Math.max(20, slideTo), t0 + dur);
    gain.gain.setValueAtTime(0.0001, t0);
    gain.gain.exponentialRampToValueAtTime(vol, t0 + 0.012);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    osc.connect(gain).connect(c.destination);
    osc.start(t0);
    osc.stop(t0 + dur + 0.02);
  }

  noise(dur, vol = 0.12, cutoff = 1200, delay = 0) {
    const c = this.init();
    if (!c) return;
    const t0 = c.currentTime + delay;
    const length = Math.max(1, Math.floor(c.sampleRate * dur));
    const buffer = c.createBuffer(1, length, c.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < length; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / length);
    const src = c.createBufferSource();
    src.buffer = buffer;
    const filter = c.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(cutoff, t0);
    filter.frequency.exponentialRampToValueAtTime(Math.max(80, cutoff * 0.25), t0 + dur);
    const gain = c.createGain();
    gain.gain.setValueAtTime(vol, t0);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    src.connect(filter).connect(gain).connect(c.destination);
    src.start(t0);
  }

  play(name) {
    if (!this.enabled) return;
    switch (name) {
      case 'select':
        this.tone(560, 0.055, 'triangle', 0.09, 720);
        break;
      case 'deny':
        this.tone(150, 0.12, 'square', 0.07, 110);
        break;
      case 'deploy':
        this.tone(210, 0.2, 'sine', 0.12, 95);
        this.noise(0.14, 0.06, 900);
        break;
      case 'enemyDeploy':
        this.tone(170, 0.18, 'sine', 0.07, 85);
        break;
      case 'hit':
        this.tone(110, 0.035, 'square', 0.035, 80);
        break;
      case 'arrow':
        this.noise(0.05, 0.035, 3600);
        break;
      case 'shot':
        this.tone(250, 0.05, 'square', 0.04, 130);
        this.noise(0.04, 0.04, 2600);
        break;
      case 'towerShot':
        this.tone(330, 0.07, 'triangle', 0.05, 180);
        break;
      case 'towerHit':
        this.tone(85, 0.13, 'sine', 0.1, 55);
        this.noise(0.08, 0.05, 500);
        break;
      case 'towerDown':
        this.noise(0.55, 0.28, 1600);
        this.tone(70, 0.6, 'sine', 0.2, 30);
        this.tone(160, 0.3, 'sawtooth', 0.06, 55, 0.03);
        break;
      case 'fireball':
        this.tone(320, 0.22, 'sawtooth', 0.07, 90);
        this.noise(0.25, 0.14, 1800);
        break;
      case 'arrows':
        this.noise(0.32, 0.1, 4200);
        this.tone(700, 0.12, 'triangle', 0.04, 300, 0.05);
        break;
      case 'crown':
        [523, 659, 784, 1047].forEach((f, i) => this.tone(f, 0.22, 'triangle', 0.1, null, i * 0.09));
        break;
      case 'win':
        [523, 659, 784, 1047, 1319].forEach((f, i) => this.tone(f, 0.32, 'triangle', 0.11, null, i * 0.12));
        this.noise(0.4, 0.05, 2400, 0.2);
        break;
      case 'lose':
        [392, 330, 262, 196].forEach((f, i) => this.tone(f, 0.34, 'sawtooth', 0.055, null, i * 0.14));
        break;
      case 'draw':
        [392, 392, 494].forEach((f, i) => this.tone(f, 0.28, 'triangle', 0.07, null, i * 0.15));
        break;
      case 'count':
        this.tone(440, 0.1, 'triangle', 0.08, null);
        break;
      case 'clash':
        this.tone(880, 0.22, 'triangle', 0.1, 1320);
        this.tone(440, 0.3, 'sine', 0.08, 660);
        break;
      default:
        break;
    }
  }
}

/* Stylized chibi troop portraits, drawn entirely with canvas paths. */

import { TEAM, clamp } from './data.js';

const OUTLINE = '#0d1624';

function rr(c, x, y, w, h, r) {
  const q = Math.min(r, w / 2, h / 2);
  c.beginPath();
  c.moveTo(x + q, y);
  c.arcTo(x + w, y, x + w, y + h, q);
  c.arcTo(x + w, y + h, x, y + h, q);
  c.arcTo(x, y + h, x, y, q);
  c.arcTo(x, y, x + w, y, q);
  c.closePath();
}

function fill(c, color) {
  c.fillStyle = color;
  c.fill();
}

function stroke(c, width = 2, color = OUTLINE) {
  c.lineWidth = width;
  c.strokeStyle = color;
  c.lineJoin = 'round';
  c.stroke();
}

function limb(c, x1, y1, x2, y2, width, color) {
  c.beginPath();
  c.moveTo(x1, y1);
  c.lineTo(x2, y2);
  c.lineCap = 'round';
  c.lineWidth = width;
  c.strokeStyle = color;
  c.stroke();
}

export function drawTroopShadow(c, r, flying = false) {
  c.save();
  c.globalAlpha *= flying ? 0.22 : 0.3;
  c.fillStyle = '#07110b';
  c.beginPath();
  c.ellipse(0, flying ? 12 : 2, r * (flying ? 0.8 : 1.05), r * (flying ? 0.3 : 0.46), 0, 0, Math.PI * 2);
  c.fill();
  c.restore();
}

export function drawTroop(c, type, r, teamKey, opts = {}) {
  const team = TEAM[teamKey];
  const facing = opts.facing === -1 ? -1 : 1;
  const walk = opts.walk || 0;
  const moving = Boolean(opts.moving);
  const bob = moving ? Math.sin(walk * 13) * r * 0.09 : Math.sin(walk * 2.2) * r * 0.03;
  const flash = clamp(opts.flash || 0, 0, 1);

  c.save();
  if (opts.alpha !== undefined) c.globalAlpha *= opts.alpha;
  c.translate(0, bob);
  c.scale(facing, 1);
  c.lineJoin = 'round';

  switch (type) {
    case 'knight': drawKnight(c, r, team); break;
    case 'archers': drawArcher(c, r, team); break;
    case 'giant': drawGiant(c, r, team); break;
    case 'goblins': drawGoblin(c, r, team); break;
    case 'musketeer': drawMusketeer(c, r, team); break;
    case 'minions': drawMinion(c, r, team); break;
    default: drawKnight(c, r, team); break;
  }

  if (flash > 0) {
    c.globalAlpha = flash * 0.55;
    c.fillStyle = '#ffffff';
    c.beginPath();
    c.arc(0, -r * 1.15, r * 1.05, 0, Math.PI * 2);
    c.fill();
  }
  c.restore();
}

function drawKnight(c, r, team) {
  // Legs and boots
  rr(c, -r * 0.5, -r * 0.55, r * 0.36, r * 0.6, r * 0.12); fill(c, '#3d4c60'); stroke(c, r * 0.09);
  rr(c, r * 0.14, -r * 0.55, r * 0.36, r * 0.6, r * 0.12); fill(c, '#334154'); stroke(c, r * 0.09);

  // Shield behind the body
  c.save();
  c.translate(-r * 0.82, -r * 1.08);
  c.beginPath();
  c.arc(0, 0, r * 0.48, 0, Math.PI * 2);
  fill(c, team.dark);
  stroke(c, r * 0.1, '#0b1522');
  c.beginPath();
  c.arc(0, 0, r * 0.36, 0, Math.PI * 2);
  c.strokeStyle = team.main;
  c.lineWidth = r * 0.09;
  c.stroke();
  c.fillStyle = team.light;
  rr(c, -r * 0.045, -r * 0.2, r * 0.09, r * 0.4, r * 0.03); c.fill();
  rr(c, -r * 0.2, -r * 0.045, r * 0.4, r * 0.09, r * 0.03); c.fill();
  c.restore();

  // Sword
  c.save();
  c.translate(r * 0.62, -r * 1.05);
  c.rotate(-0.55);
  rr(c, 0, -r * 0.09, r * 1.05, r * 0.18, r * 0.05); fill(c, '#dbe6f5'); stroke(c, r * 0.07, '#5c6b7f');
  rr(c, -r * 0.18, -r * 0.24, r * 0.16, r * 0.48, r * 0.05); fill(c, '#e9b44c');
  rr(c, -r * 0.48, -r * 0.08, r * 0.32, r * 0.16, r * 0.06); fill(c, '#7a4a24');
  c.restore();

  // Torso
  rr(c, -r * 0.62, -r * 1.62, r * 1.24, r * 1.2, r * 0.3);
  const armor = c.createLinearGradient(-r * 0.6, -r * 1.6, r * 0.6, -r * 0.5);
  armor.addColorStop(0, '#e4edf9');
  armor.addColorStop(0.5, '#a9bacf');
  armor.addColorStop(1, '#73869e');
  fill(c, armor);
  stroke(c, r * 0.1);

  // Tabard
  rr(c, -r * 0.26, -r * 1.32, r * 0.52, r * 0.78, r * 0.08);
  fill(c, team.main);
  c.globalAlpha *= 0.9;
  rr(c, -r * 0.045, -r * 1.24, r * 0.09, r * 0.55, r * 0.03); fill(c, '#ffffff');
  c.globalAlpha /= 0.9;

  // Belt
  rr(c, -r * 0.65, -r * 0.62, r * 1.3, r * 0.18, r * 0.06); fill(c, '#55402b');
  rr(c, -r * 0.12, -r * 0.65, r * 0.24, r * 0.24, r * 0.05); fill(c, '#f0c04c');

  // Shoulders + arms
  c.beginPath(); c.arc(-r * 0.66, -r * 1.46, r * 0.3, 0, Math.PI * 2); fill(c, '#c8d5e6'); stroke(c, r * 0.09);
  c.beginPath(); c.arc(r * 0.66, -r * 1.46, r * 0.3, 0, Math.PI * 2); fill(c, '#c8d5e6'); stroke(c, r * 0.09);
  rr(c, -r * 0.86, -r * 1.34, r * 0.26, r * 0.55, r * 0.12); fill(c, '#8397ad'); stroke(c, r * 0.08);
  rr(c, r * 0.6, -r * 1.34, r * 0.26, r * 0.55, r * 0.12); fill(c, '#8397ad'); stroke(c, r * 0.08);

  // Head + helmet
  c.beginPath(); c.arc(0, -r * 1.92, r * 0.55, 0, Math.PI * 2); fill(c, '#f1c49b'); stroke(c, r * 0.09);
  c.beginPath();
  c.arc(0, -r * 1.98, r * 0.56, Math.PI * 0.9, Math.PI * 2.1);
  c.closePath();
  fill(c, '#c3d0e0');
  stroke(c, r * 0.09);
  rr(c, -r * 0.47, -r * 2.02, r * 0.94, r * 0.16, r * 0.05); fill(c, '#26384d');
  rr(c, -r * 0.06, -r * 2.45, r * 0.12, r * 0.34, r * 0.05); fill(c, '#dbe6f5');
  // Plume
  c.beginPath();
  c.moveTo(0, -r * 2.5);
  c.quadraticCurveTo(r * 0.4, -r * 2.75, r * 0.62, -r * 2.3);
  c.quadraticCurveTo(r * 0.26, -r * 2.4, r * 0.08, -r * 2.36);
  c.closePath();
  fill(c, team.main);
  stroke(c, r * 0.06);
}

function drawArcher(c, r, team) {
  // Legs
  rr(c, -r * 0.42, -r * 0.45, r * 0.3, r * 0.5, r * 0.1); fill(c, '#5b4630'); stroke(c, r * 0.08);
  rr(c, r * 0.12, -r * 0.45, r * 0.3, r * 0.5, r * 0.1); fill(c, '#4d3b28'); stroke(c, r * 0.08);

  // Quiver
  c.save();
  c.translate(-r * 0.62, -r * 1.18);
  c.rotate(0.25);
  rr(c, -r * 0.16, -r * 0.42, r * 0.32, r * 0.8, r * 0.1); fill(c, '#6b4527'); stroke(c, r * 0.08);
  for (let i = -1; i <= 1; i++) {
    limb(c, i * r * 0.08, -r * 0.4, i * r * 0.12, -r * 0.72, r * 0.05, '#e7d7b1');
    c.beginPath(); c.moveTo(i * r * 0.12, -r * 0.78); c.lineTo(i * r * 0.04, -r * 0.62); c.lineTo(i * r * 0.2, -r * 0.62); c.closePath();
    fill(c, team.main);
  }
  c.restore();

  // Bow
  c.save();
  c.translate(r * 0.6, -r * 1.15);
  c.beginPath();
  c.arc(0, 0, r * 0.72, -Math.PI * 0.62, Math.PI * 0.62);
  c.strokeStyle = '#9a6836';
  c.lineWidth = r * 0.13;
  c.lineCap = 'round';
  c.stroke();
  c.beginPath();
  c.moveTo(r * 0.02, -r * 0.66); c.lineTo(r * 0.02, r * 0.66);
  c.strokeStyle = '#f2e7ce'; c.lineWidth = r * 0.045; c.stroke();
  c.restore();

  // Torso
  rr(c, -r * 0.5, -r * 1.42, r * 1.0, r * 0.98, r * 0.28);
  fill(c, '#3e6a4c');
  stroke(c, r * 0.09);
  rr(c, -r * 0.5, -r * 0.72, r * 1.0, r * 0.2, r * 0.06); fill(c, '#6d4a2b');
  c.beginPath(); c.arc(0, -r * 0.88, r * 0.11, 0, Math.PI * 2); fill(c, '#f0c04c');

  // Head + hood
  c.beginPath(); c.arc(0, -r * 1.68, r * 0.51, 0, Math.PI * 2); fill(c, '#f1c49b'); stroke(c, r * 0.09);
  c.beginPath();
  c.arc(0, -r * 1.76, r * 0.56, Math.PI * 1.02, Math.PI * 2.12);
  c.lineTo(r * 0.5, -r * 1.4);
  c.lineTo(r * 0.3, -r * 1.42);
  c.closePath();
  fill(c, team.dark);
  stroke(c, r * 0.08);
  c.beginPath();
  c.moveTo(-r * 0.1, -r * 2.16);
  c.quadraticCurveTo(r * 0.5, -r * 2.5, r * 0.5, -r * 1.95);
  c.quadraticCurveTo(r * 0.2, -r * 2.05, r * 0.05, -r * 2.0);
  c.closePath();
  fill(c, team.main);
  stroke(c, r * 0.07);
  // Eyes
  c.fillStyle = '#26313f';
  c.beginPath(); c.arc(-r * 0.15, -r * 1.68, r * 0.055, 0, Math.PI * 2); c.fill();
  c.beginPath(); c.arc(r * 0.14, -r * 1.68, r * 0.055, 0, Math.PI * 2); c.fill();

  // Arms
  limb(c, r * 0.48, -r * 1.18, r * 0.78, -r * 0.98, r * 0.18, '#f1c49b');
  limb(c, -r * 0.5, -r * 1.18, -r * 0.74, -r * 0.98, r * 0.18, '#f1c49b');
}

function drawGiant(c, r, team) {
  // Legs
  rr(c, -r * 0.72, -r * 0.62, r * 0.54, r * 0.66, r * 0.16); fill(c, '#6b4a2a'); stroke(c, r * 0.1);
  rr(c, r * 0.18, -r * 0.62, r * 0.54, r * 0.66, r * 0.16); fill(c, '#5b3d22'); stroke(c, r * 0.1);
  rr(c, -r * 0.78, -r * 0.12, r * 0.66, r * 0.2, r * 0.08); fill(c, '#3c2a18');

  // Torso
  rr(c, -r * 0.82, -r * 1.78, r * 1.64, r * 1.3, r * 0.38);
  const skin = c.createLinearGradient(-r, -r * 1.8, r * 0.8, -r * 0.6);
  skin.addColorStop(0, '#f0bd85');
  skin.addColorStop(1, '#cf955e');
  fill(c, skin);
  stroke(c, r * 0.11);

  // Belly + belt
  c.beginPath(); c.ellipse(0, -r * 1.16, r * 0.52, r * 0.4, 0, 0, Math.PI * 2); fill(c, '#e7ae74');
  rr(c, -r * 0.86, -r * 0.78, r * 1.72, r * 0.28, r * 0.08); fill(c, '#5b3a1e');
  rr(c, -r * 0.17, -r * 0.82, r * 0.34, r * 0.3, r * 0.06); fill(c, '#f3c556');
  // Team tattoo / sash
  c.beginPath();
  c.moveTo(-r * 0.78, -r * 1.6);
  c.lineTo(r * 0.65, -r * 1.3);
  c.lineTo(r * 0.64, -r * 1.12);
  c.lineTo(-r * 0.79, -r * 1.42);
  c.closePath();
  fill(c, team.main);
  c.globalAlpha *= 0.55;

  // Arms
  rr(c, -r * 1.12, -r * 1.66, r * 0.34, r * 0.95, r * 0.16); fill(c, '#dda36c'); stroke(c, r * 0.09);
  rr(c, r * 0.78, -r * 1.66, r * 0.34, r * 0.95, r * 0.16); fill(c, '#dda36c'); stroke(c, r * 0.09);
  c.beginPath(); c.arc(-r * 1.02, -r * 0.74, r * 0.34, 0, Math.PI * 2); fill(c, '#efbc84'); stroke(c, r * 0.09);
  c.beginPath(); c.arc(r * 1.02, -r * 0.74, r * 0.34, 0, Math.PI * 2); fill(c, '#efbc84'); stroke(c, r * 0.09);

  // Head
  c.beginPath(); c.arc(0, -r * 2.02, r * 0.52, 0, Math.PI * 2); fill(c, '#f2c08a'); stroke(c, r * 0.1);
  // Hair + beard
  c.beginPath();
  c.arc(0, -r * 2.12, r * 0.54, Math.PI * 1.05, Math.PI * 2.0);
  c.closePath();
  fill(c, '#b85f2c');
  c.beginPath();
  c.moveTo(-r * 0.44, -r * 1.98);
  c.quadraticCurveTo(0, -r * 1.5, r * 0.46, -r * 2.0);
  c.quadraticCurveTo(r * 0.3, -r * 1.62, 0, -r * 1.58);
  c.quadraticCurveTo(-r * 0.3, -r * 1.64, -r * 0.44, -r * 1.98);
  c.closePath();
  fill(c, '#c46a32');
  // Eyes
  c.fillStyle = '#2a1c12';
  c.beginPath(); c.arc(-r * 0.17, -r * 2.05, r * 0.06, 0, Math.PI * 2); c.fill();
  c.beginPath(); c.arc(r * 0.17, -r * 2.05, r * 0.06, 0, Math.PI * 2); c.fill();
}

function drawGoblin(c, r, team) {
  // Legs
  rr(c, -r * 0.38, -r * 0.4, r * 0.28, r * 0.44, r * 0.1); fill(c, '#4c5f27'); stroke(c, r * 0.08);
  rr(c, r * 0.1, -r * 0.4, r * 0.28, r * 0.44, r * 0.1); fill(c, '#3e4e1f'); stroke(c, r * 0.08);

  // Dagger
  c.save();
  c.translate(r * 0.55, -r * 1.0);
  c.rotate(-0.55);
  c.beginPath();
  c.moveTo(0, -r * 0.09);
  c.lineTo(r * 0.72, 0);
  c.lineTo(0, r * 0.09);
  c.closePath();
  fill(c, '#dbe6f5');
  stroke(c, r * 0.06, '#58687c');
  rr(c, -r * 0.14, -r * 0.15, r * 0.2, r * 0.3, r * 0.05); fill(c, '#a97734');
  c.restore();

  // Torso
  rr(c, -r * 0.46, -r * 1.32, r * 0.92, r * 0.94, r * 0.26); fill(c, '#6d4b2b'); stroke(c, r * 0.09);
  rr(c, -r * 0.46, -r * 0.8, r * 0.92, r * 0.2, r * 0.06); fill(c, '#3c2a18');
  c.beginPath(); c.arc(0, -r * 0.74, r * 0.1, 0, Math.PI * 2); fill(c, '#f0c04c');

  // Head
  c.beginPath(); c.arc(0, -r * 1.6, r * 0.56, 0, Math.PI * 2); fill(c, '#7fce4f'); stroke(c, r * 0.09);
  // Ears
  c.beginPath(); c.moveTo(-r * 0.48, -r * 1.62); c.lineTo(-r * 1.08, -r * 1.85); c.lineTo(-r * 0.5, -r * 1.37); c.closePath(); fill(c, '#6cbb40'); stroke(c, r * 0.07);
  c.beginPath(); c.moveTo(r * 0.48, -r * 1.62); c.lineTo(r * 1.08, -r * 1.85); c.lineTo(r * 0.5, -r * 1.37); c.closePath(); fill(c, '#6cbb40'); stroke(c, r * 0.07);
  // Eyes
  c.fillStyle = '#fff8dc';
  c.beginPath(); c.ellipse(-r * 0.18, -r * 1.66, r * 0.13, r * 0.15, 0, 0, Math.PI * 2); c.fill();
  c.beginPath(); c.ellipse(r * 0.18, -r * 1.66, r * 0.13, r * 0.15, 0, 0, Math.PI * 2); c.fill();
  c.fillStyle = '#17210c';
  c.beginPath(); c.arc(-r * 0.15, -r * 1.64, r * 0.06, 0, Math.PI * 2); c.fill();
  c.beginPath(); c.arc(r * 0.21, -r * 1.64, r * 0.06, 0, Math.PI * 2); c.fill();
  // Grin
  c.beginPath(); c.arc(0, -r * 1.46, r * 0.22, 0.15, Math.PI - 0.15); c.strokeStyle = '#24340f'; c.lineWidth = r * 0.055; c.stroke();
  c.fillStyle = '#e9f7d6';
  c.beginPath(); c.moveTo(-r * 0.08, -r * 1.38); c.lineTo(-r * 0.02, -r * 1.28); c.lineTo(r * 0.04, -r * 1.38); c.closePath(); c.fill();
  // Team bandana
  rr(c, -r * 0.58, -r * 1.92, r * 1.16, r * 0.18, r * 0.08); fill(c, team.main); stroke(c, r * 0.06, '#0d1624');
}

function drawMusketeer(c, r, team) {
  // Legs
  rr(c, -r * 0.44, -r * 0.5, r * 0.32, r * 0.56, r * 0.1); fill(c, '#4b3a63'); stroke(c, r * 0.08);
  rr(c, r * 0.12, -r * 0.5, r * 0.32, r * 0.56, r * 0.1); fill(c, '#3f3054'); stroke(c, r * 0.08);

  // Rifle
  c.save();
  c.translate(r * 0.15, -r * 1.25);
  c.rotate(-0.42);
  rr(c, -r * 0.1, -r * 0.13, r * 1.35, r * 0.14, r * 0.05); fill(c, '#5d3d22');
  rr(c, r * 0.55, -r * 0.15, r * 0.85, r * 0.11, r * 0.04); fill(c, '#c7d3e2');
  rr(c, r * 0.52, -r * 0.2, r * 0.14, r * 0.22, r * 0.04); fill(c, '#e6b65a');
  c.restore();

  // Coat
  rr(c, -r * 0.58, -r * 1.6, r * 1.16, r * 1.18, r * 0.26);
  const coat = c.createLinearGradient(-r * 0.6, -r * 1.6, r * 0.6, -r * 0.5);
  coat.addColorStop(0, '#7d68b8');
  coat.addColorStop(1, '#4a3a7c');
  fill(c, coat);
  stroke(c, r * 0.1);
  rr(c, -r * 0.1, -r * 1.58, r * 0.2, r * 1.1, r * 0.06); fill(c, team.main);
  // Buttons
  for (let i = 0; i < 3; i++) {
    c.beginPath(); c.arc(r * 0.3, -r * (1.34 - i * 0.22), r * 0.045, 0, Math.PI * 2); fill(c, '#f3cf7a');
  }
  // Shoulder pads
  c.beginPath(); c.ellipse(-r * 0.62, -r * 1.45, r * 0.28, r * 0.2, -0.3, 0, Math.PI * 2); fill(c, team.dark); stroke(c, r * 0.07);
  c.beginPath(); c.ellipse(r * 0.62, -r * 1.45, r * 0.28, r * 0.2, 0.3, 0, Math.PI * 2); fill(c, team.dark); stroke(c, r * 0.07);

  // Head
  c.beginPath(); c.arc(0, -r * 1.86, r * 0.5, 0, Math.PI * 2); fill(c, '#f1c49b'); stroke(c, r * 0.09);
  // Hair
  c.beginPath(); c.arc(0, -r * 1.88, r * 0.52, Math.PI * 0.85, Math.PI * 2.05); c.closePath(); fill(c, '#5a3d2b');

  // Hat
  c.save();
  c.translate(0, -r * 2.16);
  c.rotate(-0.12);
  c.beginPath(); c.ellipse(0, 0, r * 0.94, r * 0.22, 0, 0, Math.PI * 2); fill(c, '#3b2e52'); stroke(c, r * 0.07);
  rr(c, -r * 0.52, -r * 0.42, r * 1.04, r * 0.44, r * 0.12); fill(c, '#4a3a66'); stroke(c, r * 0.07);
  rr(c, -r * 0.52, -r * 0.14, r * 1.04, r * 0.14, r * 0.04); fill(c, team.main);
  // Feather
  c.beginPath();
  c.moveTo(r * 0.3, -r * 0.3);
  c.quadraticCurveTo(r * 0.95, -r * 0.85, r * 1.08, -r * 0.25);
  c.quadraticCurveTo(r * 0.7, -r * 0.4, r * 0.34, -r * 0.08);
  c.closePath();
  fill(c, team.light);
  stroke(c, r * 0.05);
  c.restore();

  // Arms
  limb(c, -r * 0.55, -r * 1.15, -r * 0.3, -r * 0.92, r * 0.18, '#f1c49b');
  limb(c, r * 0.52, -r * 1.18, r * 0.34, -r * 0.95, r * 0.18, '#f1c49b');
}

function drawMinion(c, r, team) {
  c.save();
  c.translate(0, -r * 1.15);
  const flap = Math.sin((c.__walk || 0) * 9) * r * 0.12;

  // Wings
  c.save();
  c.globalAlpha *= 0.85;
  c.beginPath();
  c.moveTo(-r * 0.35, -r * 0.2);
  c.quadraticCurveTo(-r * 1.4, -r * (1.0 + flap / r * 0.4), -r * 1.15, r * 0.28);
  c.quadraticCurveTo(-r * 0.75, r * 0.12, -r * 0.35, r * 0.18);
  c.closePath();
  fill(c, team.dark);
  stroke(c, r * 0.07, '#141a32');
  c.beginPath();
  c.moveTo(r * 0.35, -r * 0.2);
  c.quadraticCurveTo(r * 1.4, -r * (1.0 + flap / r * 0.4), r * 1.15, r * 0.28);
  c.quadraticCurveTo(r * 0.75, r * 0.12, r * 0.35, r * 0.18);
  c.closePath();
  fill(c, team.dark);
  stroke(c, r * 0.07, '#141a32');
  c.restore();

  // Body
  c.beginPath(); c.ellipse(0, 0, r * 0.58, r * 0.72, 0, 0, Math.PI * 2);
  const body = c.createLinearGradient(0, -r * 0.7, 0, r * 0.7);
  body.addColorStop(0, '#7b68c9');
  body.addColorStop(1, '#463780');
  fill(c, body);
  stroke(c, r * 0.09, '#17122e');

  // Belly
  c.beginPath(); c.ellipse(0, r * 0.14, r * 0.3, r * 0.34, 0, 0, Math.PI * 2); fill(c, '#a495df');

  // Horns
  c.beginPath(); c.moveTo(-r * 0.36, -r * 0.55); c.lineTo(-r * 0.5, -r * 0.92); c.lineTo(-r * 0.16, -r * 0.62); c.closePath(); fill(c, '#f0c04c'); stroke(c, r * 0.05);
  c.beginPath(); c.moveTo(r * 0.36, -r * 0.55); c.lineTo(r * 0.5, -r * 0.92); c.lineTo(r * 0.16, -r * 0.62); c.closePath(); fill(c, '#f0c04c'); stroke(c, r * 0.05);

  // Face
  c.fillStyle = '#fffbe8';
  c.beginPath(); c.ellipse(-r * 0.2, -r * 0.14, r * 0.17, r * 0.2, 0, 0, Math.PI * 2); c.fill();
  c.beginPath(); c.ellipse(r * 0.2, -r * 0.14, r * 0.17, r * 0.2, 0, 0, Math.PI * 2); c.fill();
  c.fillStyle = '#241a45';
  c.beginPath(); c.arc(-r * 0.18, -r * 0.12, r * 0.07, 0, Math.PI * 2); c.fill();
  c.beginPath(); c.arc(r * 0.22, -r * 0.12, r * 0.07, 0, Math.PI * 2); c.fill();
  // Grin
  c.beginPath(); c.arc(0, r * 0.14, r * 0.16, 0.15, Math.PI - 0.15); c.strokeStyle = '#241a45'; c.lineWidth = r * 0.06; c.stroke();
  c.fillStyle = '#fffbe8';
  c.beginPath(); c.moveTo(-r * 0.08, r * 0.25); c.lineTo(0, r * 0.38); c.lineTo(r * 0.08, r * 0.25); c.closePath(); c.fill();

  // Feet
  c.beginPath(); c.ellipse(-r * 0.22, r * 0.72, r * 0.16, r * 0.1, 0, 0, Math.PI * 2); fill(c, team.main);
  c.beginPath(); c.ellipse(r * 0.22, r * 0.72, r * 0.16, r * 0.1, 0, 0, Math.PI * 2); fill(c, team.main);

  c.restore();
}

/* Arena scenery, towers, cards, and HUD icons. */

import {
  W, H, ARENA, RIVER, LANES, BRIDGE, TEAM, ROLE_STYLE, font,
  roundRectPath, fillRoundRect, clamp, lerp,
} from './data.js';
import { drawTroop } from './troops.js';

const OUTLINE = '#0d1624';

/* ---------------------------------------------------------------- scenery */

export function buildScene() {
  const cv = document.createElement('canvas');
  cv.width = W;
  cv.height = H;
  const c = cv.getContext('2d');

  const bg = c.createLinearGradient(0, 0, 0, H);
  bg.addColorStop(0, '#0b1728');
  bg.addColorStop(0.55, '#08111f');
  bg.addColorStop(1, '#060c16');
  c.fillStyle = bg;
  c.fillRect(0, 0, W, H);

  // Arena drop shadow and rim
  c.save();
  c.shadowColor = 'rgba(0,0,0,.55)';
  c.shadowBlur = 30;
  c.shadowOffsetY = 10;
  fillRoundRect(c, ARENA.x - 6, ARENA.y - 6, ARENA.w + 12, ARENA.h + 12, ARENA.r + 6, '#16251b');
  c.restore();

  c.save();
  roundRectPath(c, ARENA.x, ARENA.y, ARENA.w, ARENA.h, ARENA.r);
  c.clip();

  const grass = c.createLinearGradient(0, ARENA.y, 0, ARENA.bottom);
  grass.addColorStop(0, '#5b9f49');
  grass.addColorStop(0.48, '#68ad50');
  grass.addColorStop(1, '#4e9340');
  c.fillStyle = grass;
  c.fillRect(ARENA.x, ARENA.y, ARENA.w, ARENA.h);

  // Mowed checker
  const tile = 52;
  for (let y = ARENA.y; y < ARENA.bottom; y += tile) {
    for (let x = ARENA.x; x < ARENA.right; x += tile) {
      const odd = ((Math.round(x / tile) + Math.round(y / tile)) % 2) === 0;
      c.fillStyle = odd ? 'rgba(255,255,255,.035)' : 'rgba(8,40,12,.045)';
      c.fillRect(x, y, tile, tile);
    }
  }

  // Soft light from the top
  const sheen = c.createRadialGradient(W / 2, RIVER.cy, 60, W / 2, RIVER.cy, 560);
  sheen.addColorStop(0, 'rgba(255,255,255,.07)');
  sheen.addColorStop(1, 'rgba(255,255,255,0)');
  c.fillStyle = sheen;
  c.fillRect(ARENA.x, ARENA.y, ARENA.w, ARENA.h);

  drawGroundDetails(c);
  drawRiverBase(c);
  c.restore();

  // Border
  roundRectPath(c, ARENA.x, ARENA.y, ARENA.w, ARENA.h, ARENA.r);
  c.strokeStyle = 'rgba(8,20,12,.6)';
  c.lineWidth = 9;
  c.stroke();
  roundRectPath(c, ARENA.x + 5, ARENA.y + 5, ARENA.w - 10, ARENA.h - 10, ARENA.r - 4);
  c.strokeStyle = 'rgba(210,240,190,.16)';
  c.lineWidth = 2;
  c.stroke();

  return cv;
}

function drawGroundDetails(c) {
  // Grass tufts
  const tufts = [
    [60, 190], [660, 230], [74, 430], [642, 420], [110, 690], [612, 668],
    [86, 900], [640, 940], [300, 160], [420, 470], [250, 990], [500, 990],
    [360, 770], [260, 400], [480, 660], [200, 640], [560, 890], [150, 870],
  ];
  c.strokeStyle = 'rgba(30,82,30,.4)';
  c.lineWidth = 2;
  for (const [x, y] of tufts) {
    c.beginPath();
    c.moveTo(x - 4, y);
    c.quadraticCurveTo(x - 6, y - 7, x - 8, y - 9);
    c.moveTo(x, y);
    c.quadraticCurveTo(x + 1, y - 9, x + 2, y - 12);
    c.moveTo(x + 4, y);
    c.quadraticCurveTo(x + 6, y - 7, x + 9, y - 9);
    c.stroke();
  }

  const flowers = [
    [102, 246, '#ffd46a'], [626, 284, '#ffb1c6'], [148, 414, '#fff2b8'], [582, 470, '#c7a6ff'],
    [90, 740, '#ffd46a'], [638, 712, '#ffb1c6'], [126, 958, '#fff2b8'], [590, 966, '#ffd46a'],
    [342, 190, '#c7a6ff'], [388, 930, '#ffb1c6'],
  ];
  for (const [x, y, col] of flowers) {
    c.fillStyle = 'rgba(20,60,20,.18)';
    c.beginPath(); c.arc(x + 1, y + 2, 4.4, 0, Math.PI * 2); c.fill();
    c.fillStyle = col;
    for (let i = 0; i < 5; i++) {
      const a = (i / 5) * Math.PI * 2;
      c.beginPath(); c.arc(x + Math.cos(a) * 3.2, y + Math.sin(a) * 3.2, 2.2, 0, Math.PI * 2); c.fill();
    }
    c.fillStyle = '#e9a11c';
    c.beginPath(); c.arc(x, y, 1.7, 0, Math.PI * 2); c.fill();
  }

  drawBush(c, 52, 350, 13);
  drawBush(c, 666, 390, 11);
  drawBush(c, 48, 830, 12);
  drawBush(c, 670, 860, 13);
  drawBush(c, 76, 130, 10);
  drawBush(c, 648, 148, 9);

  drawRock(c, 42, 560, 9, 6);
  drawRock(c, 678, 580, 8, 5);
  drawRock(c, 56, 990, 7, 5);
  drawRock(c, 664, 1000, 8, 6);
  drawRock(c, 260, 112, 6, 4);
  drawRock(c, 470, 992, 6, 4);
}

function drawBush(c, x, y, s) {
  c.save();
  c.translate(x, y);
  c.fillStyle = 'rgba(15,50,15,.25)';
  c.beginPath(); c.ellipse(2, 4, s * 1.4, s * 0.7, 0, 0, Math.PI * 2); c.fill();
  const blobs = [[-s * 0.6, 0, s * 0.75], [s * 0.35, -s * 0.2, s * 0.8], [0, -s * 0.55, s * 0.7]];
  for (const [bx, by, br] of blobs) {
    c.beginPath(); c.arc(bx, by, br, 0, Math.PI * 2);
    c.fillStyle = '#2f6a2f';
    c.fill();
    c.strokeStyle = 'rgba(10,38,12,.5)';
    c.lineWidth = 1.5;
    c.stroke();
  }
  c.fillStyle = 'rgba(150,215,120,.45)';
  c.beginPath(); c.arc(-s * 0.4, -s * 0.7, s * 0.34, 0, Math.PI * 2); c.fill();
  c.restore();
}

function drawRock(c, x, y, rx, ry) {
  c.save();
  c.translate(x, y);
  c.fillStyle = 'rgba(20,40,20,.2)';
  c.beginPath(); c.ellipse(1, 2, rx * 1.1, ry * 0.7, 0, 0, Math.PI * 2); c.fill();
  c.beginPath(); c.ellipse(0, 0, rx, ry, -0.3, 0, Math.PI * 2);
  c.fillStyle = '#8c9284';
  c.fill();
  c.strokeStyle = 'rgba(35,48,36,.55)';
  c.lineWidth = 1.5;
  c.stroke();
  c.fillStyle = 'rgba(255,255,255,.25)';
  c.beginPath(); c.ellipse(-rx * 0.25, -ry * 0.25, rx * 0.35, ry * 0.22, -0.3, 0, Math.PI * 2); c.fill();
  c.restore();
}

function drawRiverBase(c) {
  // Sandy banks
  c.fillStyle = '#c4ab69';
  c.fillRect(ARENA.x, RIVER.top - 13, ARENA.w, 13);
  c.fillRect(ARENA.x, RIVER.bottom, ARENA.w, 12);
  c.fillStyle = 'rgba(255,240,180,.25)';
  c.fillRect(ARENA.x, RIVER.top - 13, ARENA.w, 3);
  c.fillRect(ARENA.x, RIVER.bottom, ARENA.w, 3);

  const water = c.createLinearGradient(0, RIVER.top, 0, RIVER.bottom);
  water.addColorStop(0, '#2f9ccc');
  water.addColorStop(0.5, '#1d84b8');
  water.addColorStop(1, '#186e9e');
  c.fillStyle = water;
  c.fillRect(ARENA.x, RIVER.top, ARENA.w, RIVER.bottom - RIVER.top);

  // Darker deep-water band
  c.fillStyle = 'rgba(8,50,86,.2)';
  c.fillRect(ARENA.x, RIVER.cy - 8, ARENA.w, 16);

  // Reeds at the banks
  c.strokeStyle = 'rgba(52,104,42,.75)';
  c.lineWidth = 2;
  const reeds = [[78, 1], [122, 1], [312, 1], [598, 1], [646, 1], [240, 0], [420, 0], [560, 0]];
  for (const [x, side] of reeds) {
    const y = side ? RIVER.top - 10 : RIVER.bottom + 6;
    c.beginPath();
    c.moveTo(x, y);
    c.quadraticCurveTo(x - 3, y - 7, x - 5, y - 11);
    c.moveTo(x + 3, y);
    c.quadraticCurveTo(x + 5, y - 8, x + 8, y - 10);
    c.stroke();
  }
}

export function drawWater(c, time) {
  c.save();
  c.beginPath();
  c.rect(ARENA.x, RIVER.top, ARENA.w, RIVER.bottom - RIVER.top);
  c.clip();

  for (let row = 0; row < 4; row++) {
    c.beginPath();
    for (let x = ARENA.x; x <= ARENA.right; x += 14) {
      const y = RIVER.top + 9 + row * 10 + Math.sin(time * 1.7 + x * 0.024 + row * 1.3) * 2.2;
      if (x === ARENA.x) c.moveTo(x, y);
      else c.lineTo(x, y);
    }
    c.strokeStyle = `rgba(210,245,255,${0.09 + row * 0.02})`;
    c.lineWidth = 2;
    c.stroke();
  }

  for (let i = 0; i < 9; i++) {
    const x = ARENA.x + ((time * 22 + i * 79) % (ARENA.w + 30)) - 15;
    const y = RIVER.top + 8 + ((i * 37) % (RIVER.bottom - RIVER.top - 16));
    const a = 0.18 + Math.sin(time * 2 + i) * 0.08;
    c.fillStyle = `rgba(240,252,255,${a})`;
    c.beginPath(); c.ellipse(x, y, 7, 1.8, 0, 0, Math.PI * 2); c.fill();
  }

  // Sparkle near the surface
  c.fillStyle = 'rgba(255,255,255,.1)';
  c.fillRect(ARENA.x, RIVER.top + 2, ARENA.w, 2);
  c.restore();
}

export function drawBridges(c) {
  for (const bx of LANES) {
    const w = BRIDGE.half * 2;
    const y = RIVER.top - BRIDGE.pad;
    const h = (RIVER.bottom - RIVER.top) + BRIDGE.pad * 2;

    // Shadow on the water
    c.save();
    c.fillStyle = 'rgba(4,28,44,.3)';
    fillRoundRect(c, bx - w / 2 + 4, y + 7, w, h, 9, 'rgba(4,28,44,.3)');
    c.restore();

    // Deck
    const wood = c.createLinearGradient(bx - w / 2, 0, bx + w / 2, 0);
    wood.addColorStop(0, '#8f5c31');
    wood.addColorStop(0.5, '#bb8248');
    wood.addColorStop(1, '#84522a');
    roundRectPath(c, bx - w / 2, y, w, h, 8);
    c.fillStyle = wood;
    c.fill();

    c.save();
    roundRectPath(c, bx - w / 2, y, w, h, 8);
    c.clip();
    for (let py = y + 8; py < y + h; py += 11) {
      c.strokeStyle = 'rgba(70,38,14,.45)';
      c.lineWidth = 1.5;
      c.beginPath();
      c.moveTo(bx - w / 2, py);
      c.lineTo(bx + w / 2, py);
      c.stroke();
    }
    const glow = c.createLinearGradient(bx - w / 2, 0, bx + w / 2, 0);
    glow.addColorStop(0, 'rgba(255,230,170,.18)');
    glow.addColorStop(0.4, 'rgba(255,240,200,.03)');
    glow.addColorStop(1, 'rgba(60,30,10,.15)');
    c.fillStyle = glow;
    c.fillRect(bx - w / 2, y, w, h);
    c.restore();

    // Rails
    for (const side of [-1, 1]) {
      const rx = bx + side * (w / 2 - 3);
      c.strokeStyle = '#5e3a1d';
      c.lineWidth = 6;
      c.beginPath(); c.moveTo(rx, y + 2); c.lineTo(rx, y + h - 2); c.stroke();
      c.strokeStyle = '#d6a166';
      c.lineWidth = 2;
      c.beginPath(); c.moveTo(rx, y + 3); c.lineTo(rx, y + h - 3); c.stroke();
    }
    // Posts
    for (const side of [-1, 1]) {
      for (let i = 0; i < 4; i++) {
        const px = bx + side * (w / 2 - 3);
        const py = y + 10 + i * ((h - 20) / 3);
        c.beginPath(); c.arc(px, py, 4, 0, Math.PI * 2);
        c.fillStyle = '#e0b077';
        c.fill();
        c.strokeStyle = '#5e3a1d';
        c.lineWidth = 1.5;
        c.stroke();
      }
    }

    roundRectPath(c, bx - w / 2, y, w, h, 8);
    c.strokeStyle = 'rgba(45,24,8,.65)';
    c.lineWidth = 3;
    c.stroke();
  }
}

/* ----------------------------------------------------------------- towers */

export function drawTower(c, t, time) {
  const r = t.radius;
  const x = t.x;
  const y = t.y;
  const team = TEAM[t.team];

  if (!t.alive) {
    drawRubble(c, t, team, time);
    return;
  }

  const h = t.king ? r * 2.15 : r * 1.95;

  // Ground shadow
  c.fillStyle = 'rgba(8,20,10,.3)';
  c.beginPath();
  c.ellipse(x + 4, y + 9, r * 1.25, r * 0.52, 0, 0, Math.PI * 2);
  c.fill();

  // Stone base
  c.beginPath();
  c.ellipse(x, y + 2, r * 1.2, r * 0.5, 0, 0, Math.PI * 2);
  c.fillStyle = '#596259';
  c.fill();
  c.strokeStyle = 'rgba(20,30,22,.6)';
  c.lineWidth = 3;
  c.stroke();
  c.beginPath();
  c.ellipse(x, y + 1, r * 0.95, r * 0.38, 0, 0, Math.PI * 2);
  c.fillStyle = '#7b8478';
  c.fill();

  // Body
  const body = c.createLinearGradient(x - r, 0, x + r, 0);
  body.addColorStop(0, '#8b9488');
  body.addColorStop(0.35, '#c4cbbd');
  body.addColorStop(0.62, '#a1aa9d');
  body.addColorStop(1, '#788174');
  c.beginPath();
  c.moveTo(x - r * 0.82, y);
  c.lineTo(x + r * 0.82, y);
  c.lineTo(x + r * 0.63, y - h);
  c.lineTo(x - r * 0.63, y - h);
  c.closePath();
  c.fillStyle = body;
  c.fill();
  c.strokeStyle = 'rgba(30,40,32,.55)';
  c.lineWidth = 3;
  c.stroke();

  // Stone courses
  c.save();
  c.beginPath();
  c.moveTo(x - r * 0.82, y);
  c.lineTo(x + r * 0.82, y);
  c.lineTo(x + r * 0.63, y - h);
  c.lineTo(x - r * 0.63, y - h);
  c.closePath();
  c.clip();
  c.strokeStyle = 'rgba(60,70,60,.35)';
  c.lineWidth = 2;
  for (let i = 1; i < 5; i++) {
    const yy = y - (h * i) / 5;
    const halfW = lerp(r * 0.82, r * 0.63, i / 5);
    c.beginPath(); c.moveTo(x - halfW, yy); c.lineTo(x + halfW, yy); c.stroke();
    c.beginPath(); c.moveTo(x, yy); c.lineTo(x, yy - h / 5); c.stroke();
  }
  c.restore();

  // Team band
  const bandY = y - h * 0.4;
  const bandW = lerp(r * 0.82, r * 0.63, 0.4) * 2;
  c.fillStyle = team.dark;
  c.fillRect(x - bandW / 2, bandY, bandW, r * 0.22);
  c.fillStyle = team.main;
  c.fillRect(x - bandW / 2, bandY, bandW, r * 0.1);
  for (let i = -1; i <= 1; i++) {
    c.fillStyle = 'rgba(255,235,190,.85)';
    c.beginPath();
    c.moveTo(x + i * r * 0.32, bandY + r * 0.16);
    c.lineTo(x + i * r * 0.32 - r * 0.05, bandY + r * 0.06);
    c.lineTo(x + i * r * 0.32 + r * 0.05, bandY + r * 0.06);
    c.closePath();
    c.fill();
  }

  // Top platform
  c.beginPath();
  c.ellipse(x, y - h, r * 0.68, r * 0.3, 0, 0, Math.PI * 2);
  c.fillStyle = '#d3dacd';
  c.fill();
  c.strokeStyle = 'rgba(45,55,45,.6)';
  c.lineWidth = 2.5;
  c.stroke();

  // Crenellations
  const count = t.king ? 7 : 5;
  for (let i = 0; i < count; i++) {
    const a = (i / count) * Math.PI * 2 + 0.25;
    const bx = x + Math.cos(a) * r * 0.56;
    const by = y - h + Math.sin(a) * r * 0.22;
    c.save();
    c.translate(bx, by);
    c.fillStyle = '#b9c1b4';
    fillRoundRect(c, -r * 0.13, -r * 0.2, r * 0.26, r * 0.26, 2, '#b9c1b4');
    c.strokeStyle = 'rgba(45,55,45,.5)';
    c.lineWidth = 1.5;
    c.stroke();
    c.restore();
  }

  // Banner pole + flag
  const flagSide = t.team === 'blue' ? -1 : 1;
  const poleX = x + flagSide * r * 0.5;
  const poleTop = y - h - r * 1.05;
  c.strokeStyle = '#4b3725';
  c.lineWidth = 3;
  c.beginPath(); c.moveTo(poleX, y - h + 2); c.lineTo(poleX, poleTop); c.stroke();
  c.fillStyle = team.main;
  c.beginPath();
  c.moveTo(poleX, poleTop);
  c.quadraticCurveTo(poleX + flagSide * r * 0.7, poleTop + r * 0.18 + Math.sin(time * 3 + x) * 2, poleX, poleTop + r * 0.5);
  c.quadraticCurveTo(poleX + flagSide * r * 0.28, poleTop + r * 0.34, poleX, poleTop + r * 0.35);
  c.closePath();
  c.fill();
  c.strokeStyle = 'rgba(255,255,255,.35)';
  c.lineWidth = 1;
  c.stroke();

  // Door
  const doorY = y - r * 0.28;
  c.beginPath();
  c.moveTo(x - r * 0.22, y - 2);
  c.lineTo(x - r * 0.22, doorY);
  c.quadraticCurveTo(x, doorY - r * 0.34, x + r * 0.22, doorY);
  c.lineTo(x + r * 0.22, y - 2);
  c.closePath();
  c.fillStyle = '#3d3021';
  c.fill();
  c.strokeStyle = 'rgba(0,0,0,.4)';
  c.lineWidth = 2;
  c.stroke();

  // King crown
  if (t.king) {
    drawCrown(c, x, y - h - r * 0.58, r * 0.36, '#ffd45e', '#b57a10');
  }

  // Active ward glow for king
  if (t.king && t.active) {
    c.save();
    c.globalAlpha = 0.25 + Math.sin(time * 3) * 0.08;
    c.strokeStyle = team.main;
    c.lineWidth = 3;
    c.beginPath();
    c.ellipse(x, y + 4, r * 1.3, r * 0.55, 0, 0, Math.PI * 2);
    c.stroke();
    c.restore();
  }

  if (t.hitFlash > 0) {
    c.save();
    c.globalAlpha = Math.min(0.5, t.hitFlash * 2.2);
    c.fillStyle = '#fff';
    c.beginPath();
    c.ellipse(x, y - h / 2, r * 0.85, h * 0.55, 0, 0, Math.PI * 2);
    c.fill();
    c.restore();
  }

  // Health bar
  drawHealthBar(c, x - r * 0.95, y - h - r * 0.95, r * 1.9, 9, t.hp / t.maxHp, {
    bg: 'rgba(8,16,12,.72)',
    border: 'rgba(0,0,0,.45)',
  });
}

function drawRubble(c, t, team, time) {
  const r = t.radius;
  const x = t.x;
  const y = t.y;

  c.save();
  c.fillStyle = 'rgba(10,20,10,.35)';
  c.beginPath(); c.ellipse(x, y + 4, r * 1.25, r * 0.5, 0, 0, Math.PI * 2); c.fill();

  c.fillStyle = 'rgba(30,24,18,.55)';
  c.beginPath(); c.ellipse(x, y, r * 1.1, r * 0.45, 0, 0, Math.PI * 2); c.fill();

  const chunks = [
    [-0.5, 0.05, 0.34, 0.2, -0.4],
    [0.15, -0.05, 0.4, 0.22, 0.25],
    [0.55, 0.12, 0.26, 0.15, 0.7],
    [-0.1, 0.2, 0.24, 0.13, 0.1],
    [0.32, -0.18, 0.18, 0.12, -0.2],
  ];
  for (const [dx, dy, sw, sh, rot] of chunks) {
    c.save();
    c.translate(x + dx * r, y + dy * r);
    c.rotate(rot);
    c.fillStyle = '#7d867a';
    fillRoundRect(c, -r * sw / 2, -r * sh / 2, r * sw, r * sh, 3, '#7d867a');
    c.strokeStyle = 'rgba(20,28,20,.5)';
    c.lineWidth = 1.5;
    c.stroke();
    c.fillStyle = 'rgba(255,255,255,.18)';
    c.fillRect(-r * sw / 2 + 2, -r * sh / 2 + 1, r * sw - 4, 2);
    c.restore();
  }

  // Broken banner
  c.save();
  c.translate(x + r * 0.4, y - r * 0.1);
  c.rotate(0.5);
  c.fillStyle = team.dark;
  c.globalAlpha = 0.8;
  fillRoundRect(c, 0, 0, r * 0.55, r * 0.32, 2, team.dark);
  c.restore();

  // Smoke wisps
  c.save();
  for (let i = 0; i < 3; i++) {
    const a = 0.1 + Math.sin(time * 1.4 + i * 2) * 0.035;
    c.fillStyle = `rgba(210,220,215,${a})`;
    const sy = y - 12 - i * 15 - (time * 6 % 12);
    c.beginPath(); c.arc(x + Math.sin(time + i) * 7, sy, 7 + i * 4, 0, Math.PI * 2); c.fill();
  }
  c.restore();

  drawHealthBar(c, x - r * 0.9, y - r * 1.55, r * 1.8, 7, 0, {});
}

/* ------------------------------------------------------------------- cards */

export function drawCardFace(c, card, x, y, w, h, opts = {}) {
  const style = ROLE_STYLE[card.role] || ROLE_STYLE.tank;
  const lift = opts.selected ? -13 : 0;
  const affordable = opts.affordable !== false;
  const shake = opts.shake || 0;

  c.save();
  c.translate(x + shake, y + lift);

  // Drop shadow
  c.fillStyle = 'rgba(0,0,0,.42)';
  fillRoundRect(c, 3, 7, w, h, 16, 'rgba(0,0,0,.42)');

  // Body
  const bg = c.createLinearGradient(0, 0, 0, h);
  bg.addColorStop(0, style.a);
  bg.addColorStop(1, style.b);
  roundRectPath(c, 0, 0, w, h, 16);
  c.fillStyle = bg;
  c.fill();

  // Inner sheen
  c.save();
  roundRectPath(c, 0, 0, w, h, 16);
  c.clip();
  const glow = c.createRadialGradient(w / 2, h * 0.42, 4, w / 2, h * 0.42, w * 0.7);
  glow.addColorStop(0, 'rgba(255,255,255,.2)');
  glow.addColorStop(1, 'rgba(255,255,255,0)');
  c.fillStyle = glow;
  c.fillRect(0, 0, w, h);

  // Rays behind the portrait
  c.globalAlpha = 0.11;
  c.translate(w / 2, h * 0.44);
  for (let i = 0; i < 8; i++) {
    c.rotate(Math.PI / 4);
    c.fillStyle = '#ffffff';
    c.beginPath(); c.moveTo(0, 0); c.lineTo(-9, -w); c.lineTo(9, -w); c.closePath(); c.fill();
  }
  c.restore();

  // Portrait
  c.save();
  c.translate(w / 2, h * 0.66);
  if (card.spell) {
    drawSpellIcon(c, card.spell, 0, -h * 0.1, w * 0.29);
  } else {
    const r = card.id === 'giant' ? w * 0.185 : w * 0.15;
    drawTroop(c, card.id, r, 'blue', { facing: 1, walk: 0.6 });
  }
  c.restore();

  // Bottom name plate
  c.save();
  c.translate(0, h - 40);
  const plate = c.createLinearGradient(0, 0, 0, 40);
  plate.addColorStop(0, 'rgba(6,12,20,0)');
  plate.addColorStop(0.45, 'rgba(6,12,20,.82)');
  plate.addColorStop(1, 'rgba(6,12,20,.92)');
  c.fillStyle = plate;
  c.fillRect(1, 0, w - 2, 39);
  c.fillStyle = '#f6faff';
  c.font = font(13.5, 800);
  c.textAlign = 'center';
  c.textBaseline = 'middle';
  c.fillText(card.name.toUpperCase(), w / 2, 24);
  c.restore();

  // Cost badge
  drawElixirDrop(c, 23, 24, 17, true);
  c.fillStyle = '#ffffff';
  c.font = font(16, 900);
  c.textAlign = 'center';
  c.textBaseline = 'middle';
  c.fillText(String(card.cost), 23, 25);

  // Count badge
  if (card.count > 1) {
    c.save();
    c.translate(w - 19, 21);
    fillRoundRect(c, -13, -11, 26, 22, 8, 'rgba(7,14,24,.82)');
    c.strokeStyle = 'rgba(255,255,255,.22)';
    c.lineWidth = 1;
    c.stroke();
    c.fillStyle = '#eaf4ff';
    c.font = font(11, 800);
    c.textAlign = 'center';
    c.textBaseline = 'middle';
    c.fillText(`×${card.count}`, 0, 0.5);
    c.restore();
  }

  // Border
  roundRectPath(c, 1.5, 1.5, w - 3, h - 3, 14.5);
  c.strokeStyle = opts.selected ? '#ffd45e' : 'rgba(255,255,255,.18)';
  c.lineWidth = opts.selected ? 3.5 : 1.5;
  c.stroke();
  if (opts.selected) {
    c.save();
    c.shadowColor = 'rgba(255,205,80,.85)';
    c.shadowBlur = 18;
    roundRectPath(c, 1.5, 1.5, w - 3, h - 3, 14.5);
    c.strokeStyle = 'rgba(255,220,110,.8)';
    c.lineWidth = 2;
    c.stroke();
    c.restore();
  }

  // Unaffordable veil
  if (!affordable) {
    roundRectPath(c, 0, 0, w, h, 16);
    c.fillStyle = 'rgba(4,9,16,.58)';
    c.fill();
    c.fillStyle = '#ff7c8a';
    c.font = font(16, 900);
    c.textAlign = 'center';
    c.textBaseline = 'middle';
    c.fillText(String(card.cost), 23, 25);
  }

  c.restore();
}

export function drawMiniCard(c, card, x, y, w, h) {
  const style = ROLE_STYLE[card.role] || ROLE_STYLE.tank;
  c.save();
  const bg = c.createLinearGradient(0, y, 0, y + h);
  bg.addColorStop(0, style.a);
  bg.addColorStop(1, style.b);
  roundRectPath(c, x, y, w, h, 9);
  c.fillStyle = bg;
  c.fill();
  c.strokeStyle = 'rgba(255,255,255,.15)';
  c.lineWidth = 1;
  c.stroke();

  c.save();
  roundRectPath(c, x, y, w, h, 9);
  c.clip();
  c.translate(x + w / 2, y + h * 0.62);
  if (card.spell) drawSpellIcon(c, card.spell, 0, 0, w * 0.34);
  else drawTroop(c, card.id, card.id === 'giant' ? w * 0.22 : w * 0.19, 'blue', { walk: 0.5 });
  c.restore();

  drawElixirDrop(c, x + 10, y + 10, 8.5, true);
  c.fillStyle = '#fff';
  c.font = font(9.5, 900);
  c.textAlign = 'center';
  c.textBaseline = 'middle';
  c.fillText(String(card.cost), x + 10, y + 10.5);
  c.restore();
}

export function drawSpellIcon(c, kind, cx, cy, s) {
  c.save();
  c.translate(cx, cy);
  if (kind === 'fireball') {
    const glow = c.createRadialGradient(0, 0, 1, 0, 0, s * 1.5);
    glow.addColorStop(0, 'rgba(255,240,170,.9)');
    glow.addColorStop(0.4, 'rgba(255,150,40,.5)');
    glow.addColorStop(1, 'rgba(255,90,20,0)');
    c.fillStyle = glow;
    c.beginPath(); c.arc(0, 0, s * 1.5, 0, Math.PI * 2); c.fill();

    c.fillStyle = '#ffd25a';
    c.beginPath(); c.arc(0, s * 0.18, s * 0.62, 0, Math.PI * 2); c.fill();
    c.fillStyle = '#ff8a1f';
    c.beginPath(); c.arc(0, s * 0.05, s * 0.78, 0, Math.PI * 2); c.fill();
    c.fillStyle = '#fff3bd';
    c.beginPath(); c.arc(-s * 0.08, s * 0.16, s * 0.42, 0, Math.PI * 2); c.fill();

    c.fillStyle = '#ffb52e';
    for (let i = 0; i < 5; i++) {
      const a = -Math.PI * 0.9 + i * 0.45;
      c.beginPath();
      c.moveTo(Math.cos(a) * s * 0.7, Math.sin(a) * s * 0.7 + s * 0.1);
      c.quadraticCurveTo(Math.cos(a + 0.25) * s * 1.1, Math.sin(a + 0.25) * s * 1.1, Math.cos(a) * s * 1.35, Math.sin(a) * s * 1.35);
      c.quadraticCurveTo(Math.cos(a - 0.15) * s * 1.0, Math.sin(a - 0.15) * s * 1.0, Math.cos(a) * s * 0.7, Math.sin(a) * s * 0.7);
      c.closePath();
      c.fill();
    }
  } else {
    // Arrows
    c.rotate(-0.25);
    for (let i = -1; i <= 1; i++) {
      c.save();
      c.translate(i * s * 0.6, Math.abs(i) * s * 0.25);
      c.rotate(0.6);
      c.strokeStyle = '#e8cf9a';
      c.lineWidth = s * 0.13;
      c.lineCap = 'round';
      c.beginPath(); c.moveTo(0, -s * 0.95); c.lineTo(0, s * 0.7); c.stroke();
      c.fillStyle = '#c7d8ea';
      c.beginPath();
      c.moveTo(0, -s * 1.25);
      c.lineTo(-s * 0.22, -s * 0.8);
      c.lineTo(s * 0.22, -s * 0.8);
      c.closePath();
      c.fill();
      c.strokeStyle = '#9c6a35';
      c.lineWidth = s * 0.08;
      for (let f = 0; f < 2; f++) {
        c.beginPath();
        c.moveTo(0, s * (0.35 + f * 0.22));
        c.lineTo(-s * 0.24, s * (0.52 + f * 0.22));
        c.stroke();
        c.beginPath();
        c.moveTo(0, s * (0.35 + f * 0.22));
        c.lineTo(s * 0.24, s * (0.52 + f * 0.22));
        c.stroke();
      }
      c.restore();
    }
  }
  c.restore();
}

export function drawElixirDrop(c, x, y, s, withGlow = false) {
  c.save();
  c.translate(x, y);
  if (withGlow) {
    c.shadowColor = 'rgba(190,90,255,.7)';
    c.shadowBlur = 8;
  }
  c.beginPath();
  c.moveTo(0, -s);
  c.bezierCurveTo(s * 0.92, -s * 0.1, s * 0.72, s * 0.8, 0, s * 0.86);
  c.bezierCurveTo(-s * 0.72, s * 0.8, -s * 0.92, -s * 0.1, 0, -s);
  c.closePath();
  const g = c.createLinearGradient(0, -s, 0, s);
  g.addColorStop(0, '#e29bff');
  g.addColorStop(0.45, '#b44dff');
  g.addColorStop(1, '#6f1fce');
  c.fillStyle = g;
  c.fill();
  c.strokeStyle = 'rgba(46,8,83,.7)';
  c.lineWidth = 1.4;
  c.stroke();
  c.fillStyle = 'rgba(255,255,255,.55)';
  c.beginPath();
  c.ellipse(-s * 0.25, -s * 0.18, s * 0.18, s * 0.3, -0.5, 0, Math.PI * 2);
  c.fill();
  c.restore();
}

/* -------------------------------------------------------------- interface */

export function drawCrown(c, x, y, s, fill = '#ffd45e', stroke = '#b57a10') {
  c.save();
  c.translate(x, y);
  c.beginPath();
  c.moveTo(-s, s * 0.55);
  c.lineTo(-s * 0.92, -s * 0.52);
  c.lineTo(-s * 0.38, s * 0.02);
  c.lineTo(0, -s * 0.72);
  c.lineTo(s * 0.38, s * 0.02);
  c.lineTo(s * 0.92, -s * 0.52);
  c.lineTo(s, s * 0.55);
  c.closePath();
  c.fillStyle = fill;
  c.fill();
  c.strokeStyle = stroke;
  c.lineWidth = Math.max(1, s * 0.1);
  c.stroke();
  fillRoundRect(c, -s * 0.9, s * 0.5, s * 1.8, s * 0.34, s * 0.1, stroke);
  c.restore();
}

export function drawHealthBar(c, x, y, w, h, pct, opts = {}) {
  const p = clamp(pct, 0, 1);
  c.save();
  fillRoundRect(c, x - 1, y - 1, w + 2, h + 2, h / 2 + 1, opts.border || 'rgba(0,0,0,.55)');
  fillRoundRect(c, x, y, w, h, h / 2, opts.bg || 'rgba(8,14,22,.8)');
  if (p > 0) {
    const col = p > 0.55 ? '#5cd86b' : p > 0.28 ? '#ffc63d' : '#ff5c6c';
    c.save();
    roundRectPath(c, x, y, w, h, h / 2);
    c.clip();
    c.fillStyle = col;
    c.fillRect(x, y, w * p, h);
    c.fillStyle = 'rgba(255,255,255,.25)';
    c.fillRect(x, y, w * p, h * 0.4);
    c.restore();
  }
  c.restore();
}

export function drawPauseIcon(c, x, y, s, color = '#eaf4ff') {
  c.save();
  c.translate(x, y);
  fillRoundRect(c, -s * 0.48, -s * 0.6, s * 0.32, s * 1.2, s * 0.1, color);
  fillRoundRect(c, s * 0.16, -s * 0.6, s * 0.32, s * 1.2, s * 0.1, color);
  c.restore();
}

export function drawSoundIcon(c, x, y, s, enabled, color = '#eaf4ff') {
  c.save();
  c.translate(x, y);
  c.fillStyle = color;
  c.beginPath();
  c.moveTo(-s * 0.62, -s * 0.22);
  c.lineTo(-s * 0.2, -s * 0.22);
  c.lineTo(s * 0.2, -s * 0.6);
  c.lineTo(s * 0.2, s * 0.6);
  c.lineTo(-s * 0.2, s * 0.22);
  c.lineTo(-s * 0.62, s * 0.22);
  c.closePath();
  c.fill();
  c.strokeStyle = color;
  c.lineWidth = s * 0.12;
  c.lineCap = 'round';
  if (enabled) {
    c.beginPath(); c.arc(s * 0.18, 0, s * 0.4, -0.8, 0.8); c.stroke();
    c.beginPath(); c.arc(s * 0.18, 0, s * 0.68, -0.75, 0.75); c.stroke();
  } else {
    c.beginPath(); c.moveTo(s * 0.34, -s * 0.36); c.lineTo(s * 0.8, s * 0.36); c.stroke();
    c.beginPath(); c.moveTo(s * 0.8, -s * 0.36); c.lineTo(s * 0.34, s * 0.36); c.stroke();
  }
  c.restore();
}

export function drawCrownPip(c, x, y, s, earned) {
  c.save();
  if (earned) {
    c.shadowColor = 'rgba(255,205,80,.55)';
    c.shadowBlur = 8;
    drawCrown(c, x, y, s, '#ffd45e', '#b57a10');
  } else {
    c.globalAlpha = 0.22;
    drawCrown(c, x, y, s, '#b9c8da', '#5b6b7e');
  }
  c.restore();
}

export function drawShieldIcon(c, x, y, s, team) {
  const t = TEAM[team];
  c.save();
  c.translate(x, y);
  c.beginPath();
  c.moveTo(-s * 0.82, -s * 0.82);
  c.lineTo(s * 0.82, -s * 0.82);
  c.lineTo(s * 0.82, s * 0.1);
  c.quadraticCurveTo(s * 0.82, s * 0.8, 0, s * 1.02);
  c.quadraticCurveTo(-s * 0.82, s * 0.8, -s * 0.82, s * 0.1);
  c.closePath();
  const g = c.createLinearGradient(0, -s, 0, s);
  g.addColorStop(0, t.main);
  g.addColorStop(1, t.dark);
  c.fillStyle = g;
  c.fill();
  c.strokeStyle = 'rgba(6,14,24,.75)';
  c.lineWidth = 2;
  c.stroke();
  c.fillStyle = 'rgba(255,255,255,.8)';
  c.font = font(s * 0.8, 900);
  c.textAlign = 'center';
  c.textBaseline = 'middle';
  c.fillText(team === 'blue' ? 'Y' : 'R', 0, s * 0.04);
  c.restore();
}

