/* Enemy commander. Plays from the same deck, pays the same elixir. */

import { CARDS, DIFFICULTY, LANES, RIVER, ARENA, clamp, rand, pick, dist } from './data.js';

export function resetAI(g) {
  g.ai = { deck: { hand: [], queue: [], elixir: 5 }, think: rand(2, 3) };
  g.ai.deck = g.makeDeck();
  g.ai.think = rand(...DIFFICULTY[g.difficulty].think);
}

export function updateAI(g, dt) {
  if (g.finishing) return;
  const deck = g.ai.deck;
  if (!deck) return;
  g.ai.think -= dt;
  if (g.ai.think > 0) return;
  const cfg = DIFFICULTY[g.difficulty];
  g.ai.think = rand(cfg.think[0], cfg.think[1]);
  playTurn(g, cfg);
}

function playTurn(g, cfg) {
  const deck = g.ai.deck;
  const hand = deck.hand.map((id) => CARDS[id]);
  const affordable = hand
    .map((card, index) => ({ card, index }))
    .filter((o) => o.card.cost <= deck.elixir + 0.001);
  if (!affordable.length) return;

  const playerUnits = g.units.filter((u) => u.alive && u.team === 'blue' && u.deploy <= 0);
  const threats = playerUnits.filter((u) => u.y < RIVER.cy + 210);

  // 1. Value spells: clusters, or a nearly-dead tower.
  const spells = affordable.filter((o) => o.card.spell);
  if (spells.length && Math.random() < cfg.spell && castValueSpell(g, spells, playerUnits)) return;

  // 2. Defend. Better difficulties react more often.
  if (threats.length && Math.random() < cfg.defend) {
    const troops = affordable.filter((o) => !o.card.spell && o.card.targets !== 'buildings');
    let pool = troops;
    if (threats.some((u) => u.fly)) {
      const airCapable = troops.filter((o) => o.card.targets === 'all');
      if (airCapable.length) pool = airCapable;
    }
    if (pool.length) {
      // Prefer a solid defender, but don't dump the most expensive card on a lone goblin.
      pool = [...pool].sort((a, b) => b.card.cost - a.card.cost);
      const choice = threats.length >= 3 ? pool[0] : (pool[0].card.cost > 4 ? pool[pool.length - 1] : pool[0]);
      const avgX = threats.reduce((s, u) => s + u.x, 0) / threats.length;
      const lane = nearestLane(avgX);
      const threatY = Math.min(...threats.map((u) => u.y));
      const y = clamp(threatY - 95, ARENA.y + 110, RIVER.top - 24);
      if (deployTroop(g, choice, lane + rand(-22, 22), y)) return;
    }
  }

  // 3. Push. The AI waits for enough elixir and attacks the softer lane.
  if (deck.elixir >= cfg.push) {
    const troops = affordable.filter((o) => !o.card.spell);
    if (troops.length) {
      let choice = null;
      const giant = troops.find((o) => o.card.id === 'giant');
      if (giant && deck.elixir >= 7) choice = giant;
      else {
        const support = troops.filter((o) => o.card.id !== 'giant');
        choice = support.length ? pick(support) : troops[0];
      }
      const lane = pushLane(g);
      const y = choice.card.id === 'giant' ? 474 : 462;
      if (deployTroop(g, choice, lane + rand(-26, 26), y)) return;
    }
  }

  // 4. Don't sit on a full bar.
  if (deck.elixir >= 9.6) {
    const troop = pick(affordable.filter((o) => !o.card.spell));
    if (troop) deployTroop(g, troop, pick(LANES) + rand(-30, 30), 468);
  }
}

function deployTroop(g, choice, x, y) {
  const r = choice.card.radius || 10;
  const spot = findFreeSpot(g, x, y, r);
  if (!spot) return false;
  if (!g.canDeploy('red', choice.card, spot.x, spot.y)) return false;
  return g.playCard('red', choice.index, spot.x, spot.y);
}

function findFreeSpot(g, x, y, r) {
  const offsets = [
    [0, 0], [30, 0], [-30, 0], [0, -28], [0, 32], [42, -24], [-42, -24],
  ];
  for (const [dx, dy] of offsets) {
    const nx = clamp(x + dx, ARENA.x + 30, ARENA.right - 30);
    const ny = clamp(y + dy, ARENA.y + 90, RIVER.top - 24);
    if (g.canDeploy('red', { spell: false, radius: r }, nx, ny)) return { x: nx, y: ny };
  }
  return null;
}

function castValueSpell(g, spells, playerUnits) {
  for (const option of spells) {
    const card = option.card;
    let best = null;
    for (const center of playerUnits) {
      const caught = playerUnits.filter((u) => dist(u, center) <= card.radius * 0.85);
      if (!caught.length) continue;
      let score = caught.reduce((s, u) => s + Math.min(u.hp, card.dmg), 0);
      if (caught.length >= 3) score += 150;
      else if (caught.length === 2) score += 60;
      else score -= 40;
      if (!best || score > best.score) {
        const cx = caught.reduce((s, u) => s + u.x, 0) / caught.length;
        const cy = caught.reduce((s, u) => s + u.y, 0) / caught.length;
        best = { x: cx, y: cy, score, count: caught.length };
      }
    }

    // Finish a weak tower if no juicy cluster exists.
    for (const t of g.towers) {
      if (t.team !== 'blue' || !t.alive) continue;
      const towerDamage = card.dmg * card.towerMult;
      if (t.hp <= towerDamage + 8) {
        const score = 120 + (t.king ? 220 : 0);
        if (!best || score > best.score) best = { x: t.x, y: t.y, score, count: 1, tower: true };
      }
    }

    if (best && (best.count >= 2 || best.tower)) {
      const wobble = g.difficulty === 'ruthless' ? 6 : g.difficulty === 'classic' ? 14 : 26;
      g.playCard('red', option.index, best.x + rand(-wobble, wobble), best.y + rand(-wobble, wobble));
      return true;
    }
  }
  return false;
}

function nearestLane(x) {
  return Math.abs(x - LANES[0]) <= Math.abs(x - LANES[1]) ? LANES[0] : LANES[1];
}

function pushLane(g) {
  // Hit the weaker princess tower; sometimes feint to the other lane.
  if (Math.random() < 0.3) return pick(LANES);
  const left = g.towers.find((t) => t.team === 'blue' && !t.king && t.x < 360);
  const right = g.towers.find((t) => t.team === 'blue' && !t.king && t.x > 360);
  if (left && right && left.alive !== right.alive) return left.alive ? left.x : right.x;
  if (left && right) return left.hp <= right.hp ? left.x : right.x;
  return pick(LANES);
}

/* Match lifecycle, simulation, combat, and player input. */

import {
  W, H, ARENA, RIVER, LANES, TEAM, DIFFICULTY, CARDS, TOWER,
  HAND, ELIXIR, clamp, rand, pick, dist, makeDeck, formatTime,
  pointInArena, insideRect, fillRoundRect,
} from './data.js';
import { buildScene } from './art.js';
import { Sound } from './audio.js';
import { resetAI, updateAI } from './ai.js';
import { render } from './render.js';

export class Game {
  constructor() {
    this.canvas = document.getElementById('game');
    this.ctx = this.canvas.getContext('2d');
    this.sound = new Sound();
    this.scene = buildScene();
    this.time = 0;
    this.difficulty = 'classic';
    this.state = 'menu';
    this.sfxAt = {};
    this.endTimer = null;
    this.finishTimer = null;
    this.overlayTimer = null;
    this.bindUI();
    this.bindInput();
    this.resetBoard();
    this.showMenu();
    window.__miniClash = this;
  }

  /* ------------------------------------------------------------- lifecycle */

  resetBoard() {
    clearTimeout(this.finishTimer);
    clearTimeout(this.overlayTimer);
    this.finishTimer = null;
    this.overlayTimer = null;
    this.units = [];
    this.towers = [];
    this.projectiles = [];
    this.particles = [];
    this.floaters = [];
    this.rings = [];
    this.scorches = [];
    this.pendingSpells = [];
    this.banner = null;
    this.shake = 0;
    this.clashFlash = 0;
    this.selected = null;
    this.drag = null;
    this.denied = null;
    this.finishing = false;
    this.result = null;
    this.overtime = false;
    this.doubleShown = false;
    this.timeLeft = 180;
    this.matchTime = 0;
    this.countdown = 0;
    this.stats = { cardsPlayed: 0, elixirSpent: 0 };
    this.pointer = { x: W / 2, y: RIVER.cy + 90, inside: false };
    this.playerDeck = makeDeck(5);
    this.makeTowers();
    resetAI(this);
  }

  makeDeck() {
    return makeDeck(5);
  }

  makeTowers() {
    const mk = (team, kind, x, y) => {
      const def = TOWER[kind];
      const king = kind === 'king';
      return {
        team, king, x, y, radius: def.radius,
        hp: def.hp, maxHp: def.hp, dmg: def.dmg, hit: def.hit, range: def.range,
        cooldown: rand(0.5, 1.1), active: !king, alive: true, hitFlash: 0,
        isTower: true, aim: 0,
      };
    };
    this.towers = [
      mk('red', 'king', 360, 212),
      mk('red', 'princess', 190, 334),
      mk('red', 'princess', 530, 334),
      mk('blue', 'princess', 190, 778),
      mk('blue', 'princess', 530, 778),
      mk('blue', 'king', 360, 900),
    ];
  }

  startRound() {
    this.resetBoard();
    this.state = 'countdown';
    this.countdown = 3.4;
    this.lastCount = 4;
    this.hideOverlay();
    this.sound.init();
    this.sound.play('count');
  }

  showMenu() {
    this.resetBoard();
    this.state = 'menu';
    this.sound.init();
    this.showPanel('menu');
  }

  pause() {
    if (this.state !== 'playing') return;
    this.state = 'paused';
    this.selected = null;
    this.drag = null;
    this.showPanel('pause');
  }

  resume() {
    if (this.state !== 'paused') return;
    this.state = 'playing';
    this.hideOverlay();
    this.sound.play('select');
  }

  restart() {
    this.startRound();
  }

  finish(result) {
    if (this.state === 'ended') return;
    clearTimeout(this.finishTimer);
    clearTimeout(this.overlayTimer);
    this.finishTimer = null;
    this.finishing = false;
    this.state = 'ended';
    this.result = result;
    this.selected = null;
    this.drag = null;
    this.sound.play(result);
    if (result === 'win') {
      for (let i = 0; i < 4; i++) {
        this.burst(ARENA.x + rand(80, ARENA.w - 80), ARENA.y + rand(100, 500), ['#ffd45e', '#ffffff', '#5ee5c2'][i % 3], 12, 190, { gravity: 120, size: [3, 6] });
      }
    }
    this.overlayTimer = setTimeout(() => this.showEnd(), 850);
  }

  queueFinish(result, delay = 1000) {
    if (this.finishing || this.state !== 'playing') return;
    this.finishing = true;
    this.finishTimer = setTimeout(() => {
      this.finishTimer = null;
      this.finish(result);
    }, delay);
  }

  showEnd() {
    const blue = this.crowns('blue');
    const red = this.crowns('red');
    const title = document.getElementById('end-title');
    const eyebrow = document.getElementById('end-eyebrow');
    const sub = document.getElementById('end-sub');
    const crowns = document.getElementById('end-crowns');
    const stats = document.getElementById('end-stats');

    title.className = 'result-title' + (this.result === 'lose' ? ' lose' : this.result === 'draw' ? ' draw' : '');
    title.textContent = this.result === 'win' ? 'Victory' : this.result === 'lose' ? 'Defeat' : 'Draw';
    eyebrow.textContent = this.overtime ? 'OVERTIME RESULT' : 'MATCH COMPLETE';
    sub.textContent = this.result === 'win'
      ? (blue >= 3 ? 'A flawless three-crown sweep.' : 'The arena is yours. Wear the crown well.')
      : this.result === 'lose'
        ? 'They found the gap. Queue up and take it back.'
        : 'Neither side blinked. The crowns stay split.';
    crowns.innerHTML = '';
    for (let i = 0; i < 3; i++) {
      const pip = document.createElement('span');
      pip.className = 'crown-pip' + (i < blue ? ' on' : '');
      pip.textContent = '♛';
      crowns.appendChild(pip);
    }
    const rows = [
      ['Your crowns', String(blue)],
      ['Rival crowns', String(red)],
      ['Cards played', String(this.stats.cardsPlayed)],
      ['Match time', formatTime(this.matchTime)],
      ['Difficulty', DIFFICULTY[this.difficulty].label],
    ];
    stats.innerHTML = rows.map(([label, value]) =>
      `<div class="stat-row"><span>${label}</span><span>${value}</span></div>`).join('');
    this.showPanel('end');
  }

  /* ------------------------------------------------------------------- ui */

  showPanel(which) {
    const overlay = document.getElementById('overlay');
    const panels = {
      menu: document.getElementById('menu-panel'),
      end: document.getElementById('end-panel'),
      pause: document.getElementById('pause-panel'),
    };
    overlay.classList.remove('hidden');
    for (const [key, panel] of Object.entries(panels)) panel.classList.toggle('hidden', key !== which);
  }

  hideOverlay() {
    document.getElementById('overlay').classList.add('hidden');
  }

  bindUI() {
    document.querySelectorAll('.chip').forEach((chip) => {
      chip.addEventListener('click', () => {
        this.difficulty = chip.dataset.difficulty;
        document.querySelectorAll('.chip').forEach((c) => c.classList.toggle('selected', c === chip));
        this.sound.play('select');
      });
    });
    document.getElementById('play-btn').addEventListener('click', () => this.startRound());
    document.getElementById('again-btn').addEventListener('click', () => this.startRound());
    document.getElementById('menu-btn').addEventListener('click', () => this.showMenu());
    document.getElementById('resume-btn').addEventListener('click', () => this.resume());
    document.getElementById('restart-btn').addEventListener('click', () => this.startRound());
    document.getElementById('quit-btn').addEventListener('click', () => this.showMenu());
  }

  /* ---------------------------------------------------------------- input */

  toPoint(e) {
    const rect = this.canvas.getBoundingClientRect();
    return {
      x: ((e.clientX - rect.left) / rect.width) * W,
      y: ((e.clientY - rect.top) / rect.height) * H,
    };
  }

  bindInput() {
    const c = this.canvas;
    c.addEventListener('pointerdown', (e) => this.onPointerDown(e));
    c.addEventListener('pointermove', (e) => {
      const p = this.toPoint(e);
      this.pointer.x = p.x;
      this.pointer.y = p.y;
      this.pointer.inside = pointInArena(p.x, p.y, 2);
      if (this.selected !== null && this.state === 'playing') c.style.cursor = 'crosshair';
      else c.style.cursor = 'default';
    });
    c.addEventListener('pointerup', (e) => this.onPointerUp(e));
    c.addEventListener('pointercancel', () => { this.drag = null; });
    c.addEventListener('pointerleave', () => { this.pointer.inside = false; });
    c.addEventListener('contextmenu', (e) => {
      e.preventDefault();
      if (this.state === 'playing') this.selected = null;
    });

    window.addEventListener('keydown', (e) => {
      if (e.key === ' ' || e.key === 'Escape') {
        if (this.state === 'playing') {
          e.preventDefault();
          if (e.key === 'Escape' && this.selected !== null) { this.selected = null; return; }
          this.pause();
        } else if (this.state === 'paused') {
          e.preventDefault();
          this.resume();
        }
        return;
      }
      if (this.state !== 'playing') return;
      if (e.key >= '1' && e.key <= '4') {
        const i = Number(e.key) - 1;
        if (i < this.playerDeck.hand.length) this.selectCard(i);
      }
      if (e.key.toLowerCase() === 'm') {
        this.sound.toggle();
      }
    });

    document.addEventListener('visibilitychange', () => {
      if (document.hidden && this.state === 'playing') this.pause();
    });
  }

  onPointerDown(e) {
    e.preventDefault();
    this.sound.init();
    const p = this.toPoint(e);
    this.pointer.x = p.x;
    this.pointer.y = p.y;
    this.pointer.inside = pointInArena(p.x, p.y, 2);

    if (this.hitCircle(p, 42, 47, 24)) {
      if (this.state === 'playing') this.pause();
      return;
    }
    if (this.hitCircle(p, 678, 47, 24)) {
      this.sound.toggle();
      return;
    }

    if (this.state !== 'playing' || this.finishing) return;

    const idx = this.cardAt(p);
    if (idx >= 0) {
      this.selectCard(idx);
      if (this.selected !== null) {
        this.drag = { id: e.pointerId, moved: false, startX: p.x, startY: p.y };
        try { this.canvas.setPointerCapture(e.pointerId); } catch { /* ignore */ }
      }
      return;
    }

    if (this.selected !== null && pointInArena(p.x, p.y, 2)) {
      this.tryDeploy(p.x, p.y);
    }
  }

  onPointerUp(e) {
    if (!this.drag) return;
    const p = this.toPoint(e);
    this.pointer.x = p.x;
    this.pointer.y = p.y;
    if (this.state === 'playing' && this.selected !== null && pointInArena(p.x, p.y, 2)) {
      this.tryDeploy(p.x, p.y);
    }
    this.drag = null;
  }

  hitCircle(p, x, y, r) {
    return Math.hypot(p.x - x, p.y - y) <= r;
  }

  selectCard(i) {
    if (this.state !== 'playing') return;
    if (this.selected === i) {
      this.selected = null;
      return;
    }
    if (!this.canAfford(i)) {
      this.denied = { i, t: 0.3 };
      this.sound.play('deny');
      return;
    }
    this.selected = i;
    this.sound.play('select');
  }

  cardRect(i) {
    return { x: HAND.x + i * (HAND.cardW + HAND.gap), y: HAND.y, w: HAND.cardW, h: HAND.cardH };
  }

  cardAt(p) {
    for (let i = 0; i < 4; i++) {
      if (insideRect(p.x, p.y, this.cardRect(i))) return i;
    }
    return -1;
  }

  canAfford(i) {
    const id = this.playerDeck && this.playerDeck.hand[i];
    if (!id) return false;
    return this.playerDeck.elixir + 0.001 >= CARDS[id].cost;
  }

  tryDeploy(x, y) {
    if (this.selected === null || this.state !== 'playing') return;
    const i = this.selected;
    const card = CARDS[this.playerDeck.hand[i]];
    if (!card) return;
    if (!this.canAfford(i)) {
      this.denied = { i, t: 0.3 };
      this.sound.play('deny');
      return;
    }
    if (!this.canDeploy('blue', card, x, y)) {
      this.denied = { i, t: 0.3 };
      this.sound.play('deny');
      this.addFloater(x, y - 10, 'Not there', '#ff8d98', 12, 0.7);
      return;
    }
    this.playCard('blue', i, x, y);
    this.selected = null;
    this.drag = null;
  }

  canDeploy(team, card, x, y) {
    if (!card) return false;
    if (card.spell) return pointInArena(x, y, 10);
    const r = card.radius || 10;
    const minY = team === 'blue' ? RIVER.bottom + 8 : ARENA.y + 20;
    const maxY = team === 'blue' ? ARENA.bottom - 22 : RIVER.top - 8;
    if (x < ARENA.x + 18 + r || x > ARENA.right - 18 - r) return false;
    if (y < minY || y > maxY) return false;
    for (const t of this.towers) {
      if (!t.alive) continue;
      if (Math.hypot(x - t.x, y - t.y) < t.radius + r + 4) return false;
    }
    return true;
  }

  /* --------------------------------------------------------------- update */

  update(dt) {
    this.time += dt;
    this.stepEffects(dt);

    if (this.state === 'countdown') {
      this.countdown -= dt;
      const n = Math.ceil(this.countdown - 0.4);
      if (n !== this.lastCount && n >= 1 && n <= 3) {
        this.lastCount = n;
        this.sound.play('count');
      }
      if (this.countdown <= 0.4 && this.lastCount !== 0) {
        this.lastCount = 0;
        this.clashFlash = 1.0;
        this.sound.play('clash');
      }
      if (this.countdown <= 0) {
        this.countdown = 0;
        this.state = 'playing';
      }
      return;
    }

    if (this.state !== 'playing') return;

    this.matchTime += dt;
    this.updateClock(dt);
    if (this.state !== 'playing') return;

    this.regenElixir(dt);
    updateAI(this, dt);
    this.updateUnits(dt);
    this.updateTowers(dt);
    this.updateSpells(dt);
    this.updateProjectiles(dt);
    this.cleanup();
  }

  stepEffects(dt) {
    if (this.banner) {
      this.banner.t += dt;
      if (this.banner.t >= this.banner.dur) this.banner = null;
    }
    if (this.clashFlash > 0) this.clashFlash = Math.max(0, this.clashFlash - dt);
    if (this.denied) {
      this.denied.t -= dt;
      if (this.denied.t <= 0) this.denied = null;
    }
    this.shake = Math.max(0, this.shake - dt * 26);

    for (const p of this.particles) {
      p.life -= dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vy += p.gravity * dt;
      p.vx *= 1 - 1.8 * dt;
      p.vy *= 1 - 0.6 * dt;
    }
    this.particles = this.particles.filter((p) => p.life > 0);
    if (this.particles.length > 300) this.particles.splice(0, this.particles.length - 300);

    for (const f of this.floaters) {
      f.t += dt;
      f.y -= 30 * dt;
    }
    this.floaters = this.floaters.filter((f) => f.t < f.dur);

    for (const r of this.rings) {
      r.t += dt;
    }
    this.rings = this.rings.filter((r) => r.t < r.dur);
  }

  updateClock(dt) {
    this.timeLeft -= dt;
    if (!this.overtime && this.timeLeft <= 60 && !this.doubleShown) {
      this.doubleShown = true;
      this.showBanner('DOUBLE ELIXIR', 'Elixir flows twice as fast', '#c693ff', 2.4);
      this.sound.play('crown');
    }
    if (this.timeLeft > 0) return;
    this.timeLeft = 0;
    const blue = this.crowns('blue');
    const red = this.crowns('red');
    if (!this.overtime) {
      if (blue === red) {
        this.overtime = true;
        this.timeLeft = 60;
        this.showBanner('OVERTIME', 'First tower destroyed wins', '#ff8f9b', 3);
        this.sound.play('crown');
      } else {
        this.finish(blue > red ? 'win' : 'lose');
      }
    } else {
      this.finish(blue === red ? 'draw' : blue > red ? 'win' : 'lose');
    }
  }

  elixirMultiplier() {
    return this.overtime || this.timeLeft <= 60 ? 2 : 1;
  }

  regenElixir(dt) {
    const gain = (dt / 2.8) * this.elixirMultiplier();
    this.playerDeck.elixir = Math.min(10, this.playerDeck.elixir + gain);
    this.ai.deck.elixir = Math.min(10, this.ai.deck.elixir + gain);
  }

  crowns(team) {
    const enemy = team === 'blue' ? 'red' : 'blue';
    const king = this.towers.find((t) => t.team === enemy && t.king);
    if (king && !king.alive) return 3;
    return this.towers.filter((t) => t.team === enemy && !t.king && !t.alive).length;
  }

  /* ---------------------------------------------------------------- units */

  updateUnits(dt) {
    for (const u of this.units) {
      if (!u.alive) continue;
      u.hitFlash = Math.max(0, u.hitFlash - dt);
      u.attackAnim = Math.max(0, u.attackAnim - dt);
      u.cooldown = Math.max(0, u.cooldown - dt);
      if (u.deploy > 0) {
        u.deploy -= dt;
        continue;
      }

      let target = u.target;
      if (target && (!target.alive || !this.canTarget(u, target))) target = null;
      if (target && !target.isTower && dist(u, target) > u.def.aggro * 1.8 + 80) target = null;

      if (target && target.isTower && u.def.targets !== 'buildings') {
        const near = this.findUnitTarget(u);
        if (near) target = near;
      }
      if (!target) {
        target = this.findUnitTarget(u) || this.findTowerTarget(u);
      }
      u.target = target;
      if (!target) {
        u.moving = false;
        continue;
      }

      const reach = dist(u, target) - (target.radius || 0);
      if (reach <= u.def.range + u.radius * 0.25 + 3) {
        u.moving = false;
        u.facing = target.x >= u.x ? 1 : -1;
        if (u.cooldown <= 0) {
          u.cooldown = u.def.hit;
          u.attackAnim = 0.2;
          this.unitAttack(u, target);
        }
      } else {
        const point = this.pathPoint(u, target);
        if (point) this.moveUnit(u, point, dt);
      }
    }
    this.separate();
  }

  canTarget(u, other) {
    if (!other || !other.alive || other.team === u.team) return false;
    if (other.isTower) return true;
    if (other.deploy > 0) return false;
    if (u.def.targets === 'buildings') return false;
    if (u.def.targets === 'ground' && other.fly) return false;
    return true;
  }

  findUnitTarget(u) {
    if (u.def.targets === 'buildings') return null;
    let best = null;
    let bestD = Infinity;
    for (const o of this.units) {
      if (!this.canTarget(u, o)) continue;
      const d = dist(u, o) - o.radius;
      if (d <= u.def.aggro && d < bestD) {
        best = o;
        bestD = d;
      }
    }
    return best;
  }

  findTowerTarget(u) {
    const enemy = u.team === 'blue' ? 'red' : 'blue';
    const princesses = this.towers.filter((t) => t.team === enemy && t.alive && !t.king);
    let pool = princesses;
    if (!pool.length) pool = this.towers.filter((t) => t.team === enemy && t.alive && t.king);
    let best = null;
    let bestScore = Infinity;
    for (const t of pool) {
      const score = Math.abs(u.x - t.x) + Math.abs(u.y - t.y) * 0.3;
      if (score < bestScore) {
        best = t;
        bestScore = score;
      }
    }
    return best;
  }

  pathPoint(u, target) {
    if (u.fly) return target;
    const uTop = u.y < RIVER.cy;
    const tTop = target.y < RIVER.cy;
    if (uTop === tTop) return target;

    const bridge = this.bestBridge(u, target);
    if (u.y > RIVER.top - 4 && u.y < RIVER.bottom + 4) {
      return { x: bridge, y: tTop ? RIVER.top - 30 : RIVER.bottom + 30 };
    }
    return { x: bridge, y: RIVER.cy };
  }

  bestBridge(u, target) {
    let best = LANES[0];
    let bestScore = Infinity;
    for (const bx of LANES) {
      const score = Math.abs(u.x - bx) + Math.abs(target.x - bx) * 0.25;
      if (score < bestScore) {
        best = bx;
        bestScore = score;
      }
    }
    return best;
  }

  moveUnit(u, dest, dt) {
    let dx = dest.x - u.x;
    let dy = dest.y - u.y;
    const d = Math.hypot(dx, dy);
    if (d < 2) {
      u.moving = false;
      return;
    }
    dx /= d;
    dy /= d;
    const step = u.def.speed * dt;
    let nx = u.x + dx * step;
    let ny = u.y + dy * step;

    if (!u.fly && ny > RIVER.top - 4 && ny < RIVER.bottom + 4) {
      const onBridge = LANES.some((bx) => Math.abs(nx - bx) < 31);
      if (!onBridge) {
        ny = u.y <= RIVER.cy ? Math.min(ny, RIVER.top - 8) : Math.max(ny, RIVER.bottom + 8);
      }
    }

    u.x = clamp(nx, ARENA.x + 12 + u.radius, ARENA.right - 12 - u.radius);
    u.y = clamp(ny, ARENA.y + 12 + u.radius, ARENA.bottom - 12 - u.radius);
    u.moving = true;
    u.walk += dt;
    if (Math.abs(dx) > 0.12) u.facing = dx > 0 ? 1 : -1;
  }

  separate() {
    for (let i = 0; i < this.units.length; i++) {
      const a = this.units[i];
      if (!a.alive || a.deploy > 0) continue;
      for (let j = i + 1; j < this.units.length; j++) {
        const b = this.units[j];
        if (!b.alive || b.deploy > 0 || a.fly !== b.fly) continue;
        const min = a.radius + b.radius;
        let dx = b.x - a.x;
        let dy = b.y - a.y;
        let d = Math.hypot(dx, dy);
        if (d >= min) continue;
        if (d < 0.001) { dx = rand(-1, 1); dy = rand(-1, 1); d = Math.hypot(dx, dy) || 1; }
        const push = (min - d) * 0.5;
        const ox = (dx / d) * push;
        const oy = (dy / d) * push;
        a.x -= ox; a.y -= oy;
        b.x += ox; b.y += oy;
      }
      if (!a.fly) {
        for (const t of this.towers) {
          if (!t.alive) continue;
          const min = t.radius + a.radius + 2;
          const dx = a.x - t.x;
          const dy = a.y - t.y;
          const d = Math.hypot(dx, dy);
          if (d < min && d > 0.001) {
            a.x = t.x + (dx / d) * min;
            a.y = t.y + (dy / d) * min;
          }
        }
      }
      a.x = clamp(a.x, ARENA.x + 10 + a.radius, ARENA.right - 10 - a.radius);
      a.y = clamp(a.y, ARENA.y + 10 + a.radius, ARENA.bottom - 10 - a.radius);
    }
  }

  unitAttack(u, target) {
    if (u.def.kind === 'ranged') {
      const speed = u.def.projectile === 'bullet' ? 700 : 520;
      this.spawnProjectile({
        x: u.x + u.facing * u.radius * 0.6,
        y: u.y - u.radius * 1.3,
        target,
        team: u.team,
        dmg: u.def.dmg,
        speed,
        kind: u.def.projectile,
      });
      this.sfx(u.def.projectile === 'bullet' ? 'shot' : 'arrow', 0.07);
    } else {
      this.applyDamage(target, u.def.dmg, u.team);
      this.burst(target.x, target.y - (target.isTower ? 20 : 10), '#fff2b8', 4, 90, { gravity: 60, size: [1.5, 3] });
      this.sfx('hit', 0.055);
    }
  }

  /* --------------------------------------------------------------- towers */

  updateTowers(dt) {
    for (const t of this.towers) {
      if (!t.alive) continue;
      t.hitFlash = Math.max(0, t.hitFlash - dt);
      if (!t.active) continue;
      t.cooldown -= dt;
      if (t.cooldown > 0) continue;

      let best = null;
      let bestD = Infinity;
      for (const u of this.units) {
        if (!u.alive || u.team === t.team || u.deploy > 0) continue;
        const d = dist(t, u);
        if (d <= t.range + u.radius && d < bestD) {
          best = u;
          bestD = d;
        }
      }
      if (best) {
        t.cooldown = t.hit;
        this.spawnProjectile({
          x: t.x,
          y: t.y - (t.king ? 82 : 60),
          target: best,
          team: t.team,
          dmg: t.dmg,
          speed: 620,
          kind: 'tower',
        });
        this.sfx('towerShot', 0.09);
      } else {
        t.cooldown = 0.12;
      }
    }
  }

  /* ----------------------------------------------------------- projectiles */

  spawnProjectile({ x, y, target, team, dmg, speed, kind }) {
    this.projectiles.push({
      x, y, target, team, dmg, speed, kind, life: 2.4, angle: 0,
      lx: target ? target.x : x,
      ly: target ? target.y : y,
    });
  }

  updateProjectiles(dt) {
    for (const p of this.projectiles) {
      p.life -= dt;
      if (p.life <= 0) { p.dead = true; continue; }
      if (p.target && p.target.alive) {
        p.lx = p.target.x;
        p.ly = p.target.y - (p.target.isTower ? 30 : 10);
      }
      const dx = p.lx - p.x;
      const dy = p.ly - p.y;
      const d = Math.hypot(dx, dy);
      p.angle = Math.atan2(dy, dx);
      const step = p.speed * dt;
      if (d <= step + 6) {
        p.x = p.lx;
        p.y = p.ly;
        p.dead = true;
        if (p.target && p.target.alive) {
          this.applyDamage(p.target, p.dmg, p.team);
          const hitColor = p.kind === 'tower' ? TEAM[p.team].main : '#ffe7ae';
          this.burst(p.x, p.y, hitColor, p.kind === 'tower' ? 8 : 4, 120, { gravity: 90, size: [1.5, 3.4] });
          if (p.kind === 'tower') this.sfx('towerHit', 0.12);
        }
      } else {
        p.x += (dx / d) * step;
        p.y += (dy / d) * step;
      }
    }
    this.projectiles = this.projectiles.filter((p) => !p.dead);
  }

  /* --------------------------------------------------------------- spells */

  updateSpells(dt) {
    for (const s of this.pendingSpells) {
      s.t += dt;
      if (s.t >= s.dur) {
        s.done = true;
        this.resolveSpell(s);
      }
    }
    this.pendingSpells = this.pendingSpells.filter((s) => !s.done);
  }

  resolveSpell(s) {
    const card = s.card;
    const enemy = s.team === 'blue' ? 'red' : 'blue';
    for (const u of this.units) {
      if (!u.alive || u.team !== enemy) continue;
      if (dist(u, s) <= card.radius + u.radius * 0.6) {
        this.applyDamage(u, card.dmg, s.team);
      }
    }
    for (const t of this.towers) {
      if (!t.alive || t.team !== enemy) continue;
      if (dist(t, s) <= card.radius + t.radius * 0.55) {
        this.applyDamage(t, card.dmg * card.towerMult, s.team);
      }
    }

    const fire = card.spell === 'fireball';
    this.burst(s.x, s.y, fire ? '#ffb22e' : '#d8c08a', fire ? 36 : 22, fire ? 260 : 180, {
      gravity: fire ? 160 : 300, size: fire ? [3, 8] : [1.5, 4],
    });
    this.burst(s.x, s.y, fire ? '#fff2b0' : '#ffffff', 12, 130, { gravity: 40, size: [2, 5] });
    this.addRing(s.x, s.y, card.radius, fire ? 'rgba(255,170,60,.9)' : 'rgba(235,215,160,.8)', 0.5);
    this.addScorch(s.x, s.y, card.radius * 0.85, fire ? 0.4 : 0.2);
    this.shake = Math.max(this.shake, fire ? 18 : 9);
    this.sfx(fire ? 'boom' : 'arrows', 0.1);
  }

  /* ----------------------------------------------------------- card play */

  playCard(team, index, x, y) {
    const deck = team === 'blue' ? this.playerDeck : this.ai.deck;
    const id = deck.hand[index];
    const card = CARDS[id];
    if (!card || deck.elixir + 0.001 < card.cost) return false;
    if (!this.canDeploy(team, card, x, y)) return false;

    deck.elixir -= card.cost;
    deck.hand[index] = deck.queue.shift();
    deck.queue.push(id);

    if (team === 'blue') {
      this.stats.cardsPlayed++;
      this.stats.elixirSpent += card.cost;
      this.sound.play('deploy');
    } else {
      this.sound.play('enemyDeploy');
    }

    if (card.spell) {
      this.pendingSpells.push({
        team, card, x, y, t: 0, dur: card.spell === 'fireball' ? 0.55 : 0.5,
        fromY: y - (card.spell === 'fireball' ? 300 : 50),
      });
    } else {
      this.spawnTroop(team, card, x, y);
    }
    return true;
  }

  spawnTroop(team, card, x, y) {
    const offsets = card.count === 1
      ? [[0, 0]]
      : card.count === 2
        ? [[-15, 0], [15, 0]]
        : [[0, -11], [-17, 8], [17, 8]];
    for (const [dx, dy] of offsets) {
      const u = this.makeUnit(team, card, x + dx, y + dy);
      this.units.push(u);
    }
    this.addRing(x, y, card.radius + 16, TEAM[team].main, 0.45);
    this.burst(x, y + 4, '#e9dfc4', 10, 75, { gravity: 120, size: [2, 4] });
    this.burst(x, y + 4, TEAM[team].main, 6, 60, { gravity: 40, size: [1.5, 3] });
  }

  makeUnit(team, card, x, y) {
    return {
      def: card, team, x, y,
      hp: card.hp, maxHp: card.hp, radius: card.radius, fly: Boolean(card.flying),
      target: null, cooldown: rand(0.25, 0.65), deploy: 0.42, walk: rand(0, 4),
      facing: team === 'blue' ? 1 : -1, moving: false, hitFlash: 0,
      attackAnim: 0, alive: true,
      isUnit: true,
    };
  }

  /* -------------------------------------------------------------- damage */

  applyDamage(target, amount, team) {
    if (!target || !target.alive) return;
    target.hp -= amount;
    target.hitFlash = Math.max(target.hitFlash || 0, 0.16);
    if (target.isTower) {
      if (target.king) target.active = true;
      if (amount >= 24 && Math.random() < 0.48) {
        this.addFloater(target.x + rand(-10, 10), target.y - target.radius * 1.8, String(Math.round(amount)), '#ffe7a1', 13, 0.6);
      }
      if (target.hp <= 0) this.destroyTower(target);
    } else if (target.hp <= 0) {
      this.killUnit(target);
    }
  }

  killUnit(u) {
    if (!u.alive) return;
    u.alive = false;
    this.burst(u.x, u.y - u.radius, TEAM[u.team].main, 9, 120, { gravity: 240, size: [2, 4.5] });
    this.burst(u.x, u.y - u.radius, '#ffffff', 5, 90, { gravity: 120, size: [1, 3] });
    this.addRing(u.x, u.y, u.radius + 8, TEAM[u.team].glow, 0.28);
  }

  destroyTower(t) {
    if (!t.alive) return;
    t.alive = false;
    t.hp = 0;

    const team = TEAM[t.team];
    this.burst(t.x, t.y - 30, '#b7c0b2', 26, 230, { gravity: 260, size: [2, 7] });
    this.burst(t.x, t.y - 20, team.main, 16, 180, { gravity: 180, size: [2, 5] });
    this.burst(t.x, t.y - 15, '#ffcf5a', 12, 150, { gravity: 100, size: [2, 5] });
    this.addRing(t.x, t.y, t.radius * 2.4, team.glow, 0.8);
    this.addScorch(t.x, t.y, t.radius * 1.3, 0.45);
    this.shake = Math.max(this.shake, 26);
    this.sfx('towerDown', 0.2);
    this.addFloater(t.x, t.y - t.radius * 2.5, '+1 CROWN', '#ffd45e', 17, 1.2);

    if (!t.king) {
      const king = this.towers.find((k) => k.team === t.team && k.king);
      if (king) king.active = true;
    }

    const blue = this.crowns('blue');
    const red = this.crowns('red');
    if (t.king) {
      this.queueFinish(t.team === 'red' ? 'win' : 'lose', 1150);
    } else if (this.overtime) {
      this.queueFinish(blue === red ? 'draw' : blue > red ? 'win' : 'lose', 1000);
    } else if (!this.overtime) {
      this.sound.play('crown');
    }
  }

  /* -------------------------------------------------------------- effects */

  burst(x, y, color, count, speed, opts = {}) {
    const colors = Array.isArray(color) ? color : [color];
    for (let i = 0; i < count; i++) {
      const a = rand(0, Math.PI * 2);
      const v = rand(speed * 0.25, speed);
      const size = opts.size ? rand(opts.size[0], opts.size[1]) : rand(2, 4);
      this.particles.push({
        x, y,
        vx: Math.cos(a) * v,
        vy: Math.sin(a) * v - (opts.up || 0),
        gravity: opts.gravity === undefined ? 180 : opts.gravity,
        life: rand(0.3, 0.85),
        max: 0.85,
        size,
        color: pick(colors),
        shape: opts.shape || (Math.random() < 0.25 ? 'square' : 'circle'),
      });
    }
  }

  addRing(x, y, radius, color, dur = 0.5) {
    this.rings.push({ x, y, radius, color, t: 0, dur });
  }

  addFloater(x, y, text, color, size = 14, dur = 0.8) {
    this.floaters.push({ x, y, text, color, size, t: 0, dur });
  }

  addScorch(x, y, radius, alpha = 0.3) {
    this.scorches.push({ x, y, radius, alpha, rot: rand(0, Math.PI) });
    if (this.scorches.length > 16) this.scorches.shift();
  }

  showBanner(text, sub, color, dur = 2.2) {
    this.banner = { text, sub, color, t: 0, dur };
  }

  sfx(name, gap = 0.06) {
    const now = this.time;
    if (this.sfxAt[name] && now - this.sfxAt[name] < gap) return;
    this.sfxAt[name] = now;
    this.sound.play(name);
  }

  cleanup() {
    this.units = this.units.filter((u) => u.alive);
  }
}

const game = new Game();
let last = performance.now();
function frame(now) {
  const dt = Math.min(0.05, Math.max(0, (now - last) / 1000));
  last = now;
  game.update(dt);
  render(game);
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

/* Canvas presentation for the arena, HUD, and deploy preview. */

import {
  W, H, ARENA, RIVER, HAND, NEXT, ELIXIR, HUD, TEAM, CARDS, LANES,
  font, clamp, formatTime, pointInArena, fillRoundRect, roundRectPath, lerp,
} from './data.js';
import {
  drawWater, drawBridges, drawTower, drawCardFace, drawMiniCard, drawCrown,
  drawCrownPip, drawElixirDrop, drawPauseIcon, drawSoundIcon, drawShieldIcon,
  drawHealthBar, drawSpellIcon,
} from './art.js';
import { drawTroop, drawTroopShadow } from './troops.js';

export function render(g) {
  const c = g.ctx;
  c.clearRect(0, 0, W, H);
  c.drawImage(g.scene, 0, 0);

  const shake = g.shake > 0.2 ? g.shake : 0;
  const ox = shake ? (Math.random() * 2 - 1) * shake * 0.55 : 0;
  const oy = shake ? (Math.random() * 2 - 1) * shake * 0.4 : 0;

  c.save();
  c.translate(ox, oy);

  drawWater(c, g.time);
  drawBridges(c);

  for (const s of g.scorches) drawScorch(c, s);
  if (g.state === 'playing' && g.selected !== null) drawDeployZone(g, c);

  for (const t of g.towers) drawTower(c, t, g.time);

  if (g.state === 'menu') {
    drawMenuTroops(g, c);
    c.restore();
    return;
  }

  for (const s of g.pendingSpells) drawPendingSpell(g, c, s);

  drawUnits(g, c);
  drawProjectiles(g, c);
  drawRings(g, c);
  drawParticles(g, c);
  drawFloaters(g, c);
  drawGhost(g, c);
  c.restore();

  drawHUD(g, c);
  drawHints(g, c);
  if (g.state === 'countdown') drawCountdown(g, c);
  if (g.clashFlash > 0 && g.state === 'playing') drawClash(g, c);
  if (g.banner) drawBanner(g, c);
}

/* ------------------------------------------------------------------ arena */

function drawScorch(c, s) {
  c.save();
  c.translate(s.x, s.y);
  c.rotate(s.rot);
  const g = c.createRadialGradient(0, 0, 2, 0, 0, s.radius);
  g.addColorStop(0, `rgba(18,14,10,${s.alpha})`);
  g.addColorStop(0.6, `rgba(30,22,14,${s.alpha * 0.6})`);
  g.addColorStop(1, 'rgba(30,22,14,0)');
  c.fillStyle = g;
  c.beginPath();
  c.ellipse(0, 0, s.radius, s.radius * 0.55, 0, 0, Math.PI * 2);
  c.fill();
  c.restore();
}

function drawDeployZone(g, c) {
  const card = CARDS[g.playerDeck.hand[g.selected]];
  if (!card) return;
  const top = RIVER.bottom + 4;
  c.save();
  c.beginPath();
  c.rect(ARENA.x + 2, top, ARENA.w - 4, ARENA.bottom - top - 2);
  c.clip();
  const grad = c.createLinearGradient(0, top, 0, ARENA.bottom);
  if (card.spell) {
    grad.addColorStop(0, 'rgba(176,108,255,.16)');
    grad.addColorStop(1, 'rgba(176,108,255,.04)');
  } else {
    grad.addColorStop(0, 'rgba(74,167,255,.18)');
    grad.addColorStop(1, 'rgba(74,167,255,.03)');
  }
  c.fillStyle = grad;
  c.fillRect(ARENA.x, top, ARENA.w, ARENA.bottom - top);
  c.restore();

  if (!card.spell) {
    c.save();
    c.setLineDash([7, 7]);
    c.strokeStyle = 'rgba(120,195,255,.4)';
    c.lineWidth = 2;
    c.beginPath();
    c.moveTo(ARENA.x + 10, top);
    c.lineTo(ARENA.right - 10, top);
    c.stroke();
    c.restore();
  }
}

function drawMenuTroops(g, c) {
  const units = [
    ['knight', 'blue', 302, 700, 1, 16],
    ['archers', 'blue', 252, 648, 1, 12],
    ['giant', 'red', 470, 420, -1, 23],
    ['goblins', 'red', 418, 450, -1, 10],
  ];
  for (const [type, team, x, y, facing, r] of units) {
    c.save();
    c.translate(x, y);
    c.globalAlpha = 0.95;
    drawTroopShadow(c, r, false);
    drawTroop(c, type, r, team, { facing, walk: g.time * 0.35 + x, moving: false });
    c.restore();
  }
}

function drawUnits(g, c) {
  const units = g.units.filter((u) => u.alive).sort((a, b) => a.y - b.y);
  for (const u of units) {
    const deploying = u.deploy > 0;
    const grow = deploying ? clamp(1 - u.deploy / 0.42, 0, 1) : 1;
    const scale = deploying ? 0.35 + grow * 0.65 : 1;
    const alpha = deploying ? 0.4 + grow * 0.6 : 1;
    const lift = u.fly ? 16 : 0;

    c.save();
    c.translate(u.x, u.y);
    drawTroopShadow(c, u.radius, u.fly);
    // Team ring keeps the two sides readable at a glance.
    c.globalAlpha = 0.55;
    c.strokeStyle = TEAM[u.team].main;
    c.lineWidth = 2;
    c.beginPath();
    c.ellipse(0, 1, u.radius * 0.95, u.radius * 0.38, 0, 0, Math.PI * 2);
    c.stroke();
    c.restore();

    c.save();
    c.translate(u.x, u.y - lift);
    c.scale(scale, scale);
    if (u.attackAnim > 0) {
      const lunge = Math.sin((u.attackAnim / 0.2) * Math.PI) * 3.5;
      c.translate(u.facing * lunge, 0);
    }
    drawTroop(c, u.def.id, u.radius, u.team, {
      facing: u.facing, walk: u.walk, moving: u.moving, flash: u.hitFlash, alpha,
    });
    c.restore();

    if (!deploying && u.hp < u.maxHp) {
      const w = Math.max(26, u.radius * 2.2);
      drawHealthBar(c, u.x - w / 2, u.y - lift - u.radius * 2.85, w, 5, u.hp / u.maxHp, {});
    }
    if (deploying) {
      const p = 1 - u.deploy / 0.42;
      c.save();
      c.globalAlpha = 0.6 * (1 - p);
      c.strokeStyle = TEAM[u.team].main;
      c.lineWidth = 2.5;
      c.beginPath();
      c.ellipse(u.x, u.y, u.radius * (1 + p * 1.8), u.radius * 0.45 * (1 + p * 1.8), 0, 0, Math.PI * 2);
      c.stroke();
      c.restore();
    }
  }
}

function drawProjectiles(g, c) {
  for (const p of g.projectiles) {
    c.save();
    c.translate(p.x, p.y);
    if (p.kind === 'arrow') {
      c.rotate(p.angle);
      c.strokeStyle = '#f2dba9';
      c.lineWidth = 2.4;
      c.lineCap = 'round';
      c.beginPath(); c.moveTo(-11, 0); c.lineTo(6, 0); c.stroke();
      c.fillStyle = '#d7e4f2';
      c.beginPath(); c.moveTo(9, 0); c.lineTo(2, -3); c.lineTo(2, 3); c.closePath(); c.fill();
      c.strokeStyle = '#b9854a';
      c.lineWidth = 1.5;
      c.beginPath(); c.moveTo(-11, 0); c.lineTo(-15, -4); c.moveTo(-11, 0); c.lineTo(-15, 4); c.stroke();
    } else if (p.kind === 'bullet') {
      c.rotate(p.angle);
      c.strokeStyle = 'rgba(255,221,140,.45)';
      c.lineWidth = 2;
      c.beginPath(); c.moveTo(-14, 0); c.lineTo(-3, 0); c.stroke();
      c.fillStyle = '#ffe9a8';
      c.beginPath(); c.arc(0, 0, 4, 0, Math.PI * 2); c.fill();
      c.fillStyle = '#fff8dd';
      c.beginPath(); c.arc(0, 0, 1.8, 0, Math.PI * 2); c.fill();
    } else {
      const team = TEAM[p.team].main;
      c.fillStyle = 'rgba(255,255,255,.15)';
      c.beginPath(); c.arc(0, 0, 11, 0, Math.PI * 2); c.fill();
      c.fillStyle = team;
      c.beginPath(); c.arc(0, 0, 6.5, 0, Math.PI * 2); c.fill();
      c.fillStyle = '#ffffff';
      c.beginPath(); c.arc(-1, -1, 2.4, 0, Math.PI * 2); c.fill();
      c.strokeStyle = 'rgba(255,255,255,.35)';
      c.lineWidth = 2;
      c.beginPath(); c.moveTo(-5, 0); c.lineTo(-16, 0); c.stroke();
    }
    c.restore();
  }
}

function drawRings(g, c) {
  for (const r of g.rings) {
    const t = r.t / r.dur;
    const alpha = 1 - t;
    const radius = r.radius * (0.35 + t * 0.9);
    c.save();
    c.globalAlpha = alpha * 0.9;
    c.strokeStyle = r.color;
    c.lineWidth = 3 * (1 - t) + 1;
    c.beginPath();
    c.ellipse(r.x, r.y, radius, radius * 0.55, 0, 0, Math.PI * 2);
    c.stroke();
    c.restore();
  }
}

function drawParticles(g, c) {
  for (const p of g.particles) {
    const alpha = clamp(p.life / 0.45, 0, 1);
    c.save();
    c.globalAlpha = alpha;
    c.fillStyle = p.color;
    if (p.shape === 'square') {
      c.translate(p.x, p.y);
      c.rotate(p.x * 0.1 + p.y * 0.05);
      c.fillRect(-p.size / 2, -p.size / 2, p.size, p.size);
    } else {
      c.beginPath();
      c.arc(p.x, p.y, p.size, 0, Math.PI * 2);
      c.fill();
    }
    c.restore();
  }
}

function drawFloaters(g, c) {
  for (const f of g.floaters) {
    const t = f.t / f.dur;
    const alpha = t < 0.6 ? 1 : 1 - (t - 0.6) / 0.4;
    c.save();
    c.globalAlpha = clamp(alpha, 0, 1);
    c.font = font(f.size, 900);
    c.textAlign = 'center';
    c.textBaseline = 'middle';
    c.lineWidth = 4;
    c.strokeStyle = 'rgba(6,12,20,.7)';
    c.strokeText(f.text, f.x, f.y);
    c.fillStyle = f.color;
    c.fillText(f.text, f.x, f.y);
    c.restore();
  }
}

function drawPendingSpell(g, c, s) {
  const p = s.t / s.dur;
  const card = s.card;
  const color = card.spell === 'fireball' ? 'rgba(255,150,50,' : 'rgba(235,215,160,';

  c.save();
  const ringAlpha = 0.16 + p * 0.22;
  c.fillStyle = `${color}${ringAlpha})`;
  c.beginPath();
  c.ellipse(s.x, s.y, card.radius, card.radius * 0.6, 0, 0, Math.PI * 2);
  c.fill();
  c.strokeStyle = `${color}${0.4 + p * 0.4})`;
  c.lineWidth = 2;
  c.setLineDash([6, 6]);
  c.beginPath();
  c.ellipse(s.x, s.y, card.radius, card.radius * 0.6, 0, 0, Math.PI * 2);
  c.stroke();
  c.restore();

  if (card.spell === 'fireball') {
    const fromY = s.y - 310;
    const x = s.x + Math.sin(p * 4) * 3;
    const y = lerp(fromY, s.y, p * p);
    c.save();
    const glow = c.createRadialGradient(x, y, 2, x, y, 30);
    glow.addColorStop(0, 'rgba(255,248,190,.95)');
    glow.addColorStop(0.4, 'rgba(255,160,50,.7)');
    glow.addColorStop(1, 'rgba(255,100,20,0)');
    c.fillStyle = glow;
    c.beginPath(); c.arc(x, y, 30, 0, Math.PI * 2); c.fill();
    c.fillStyle = '#ffd35c';
    c.beginPath(); c.arc(x, y + 6, 10, 0, Math.PI * 2); c.fill();
    for (let i = 1; i <= 4; i++) {
      c.globalAlpha = 0.5 - i * 0.1;
      c.fillStyle = '#ff9a31';
      c.beginPath(); c.arc(x + rand(-3, 3), y - i * 14, 8 - i, 0, Math.PI * 2); c.fill();
    }
    c.restore();
  } else {
    c.save();
    for (let i = 0; i < 8; i++) {
      const px = s.x + ((i * 47) % 130) - 65;
      const py = s.y - 160 + ((i * 31) % 40) + p * 180;
      c.strokeStyle = 'rgba(240,225,180,.75)';
      c.lineWidth = 2;
      c.beginPath(); c.moveTo(px, py); c.lineTo(px, py + 16); c.stroke();
      c.fillStyle = '#e8eef8';
      c.beginPath(); c.moveTo(px, py + 18); c.lineTo(px - 3, py + 11); c.lineTo(px + 3, py + 11); c.closePath(); c.fill();
    }
    c.restore();
  }
}

function drawGhost(g, c) {
  if (g.state !== 'playing' || g.selected === null || !g.pointer.inside || g.finishing) return;
  const card = CARDS[g.playerDeck.hand[g.selected]];
  if (!card) return;
  const x = g.pointer.x;
  const y = g.pointer.y;
  const valid = g.canDeploy('blue', card, x, y);

  c.save();
  c.setLineDash([6, 6]);
  c.lineWidth = 2.5;
  if (card.spell) {
    const rad = card.radius;
    c.fillStyle = valid ? 'rgba(176,108,255,.16)' : 'rgba(255,80,90,.18)';
    c.strokeStyle = valid ? 'rgba(210,160,255,.9)' : 'rgba(255,110,120,.9)';
    c.beginPath();
    c.ellipse(x, y, rad, rad * 0.62, 0, 0, Math.PI * 2);
    c.fill();
    c.stroke();
    c.setLineDash([]);
    drawSpellIcon(c, card.spell, x, y, 22);
  } else {
    const rad = card.radius + 6;
    c.fillStyle = valid ? 'rgba(90,220,130,.14)' : 'rgba(255,70,90,.18)';
    c.strokeStyle = valid ? 'rgba(120,255,170,.9)' : 'rgba(255,110,120,.9)';
    c.beginPath();
    c.ellipse(x, y, rad, rad * 0.45, 0, 0, Math.PI * 2);
    c.fill();
    c.stroke();
    c.setLineDash([]);
    c.globalAlpha = valid ? 0.75 : 0.45;
    c.translate(x, y);
    drawTroopShadow(c, card.radius, card.flying);
    drawTroop(c, card.id, card.radius, 'blue', { facing: 1, walk: g.time * 4, moving: false });
  }
  c.restore();
}

/* -------------------------------------------------------------------- hud */

function drawHUD(g, c) {
  const blue = g.crowns('blue');
  const red = g.crowns('red');

  // Top bar
  const top = c.createLinearGradient(0, 0, 0, HUD.h);
  top.addColorStop(0, 'rgba(7,14,25,.98)');
  top.addColorStop(1, 'rgba(10,20,35,.9)');
  c.fillStyle = top;
  c.fillRect(0, 0, W, HUD.h);
  c.fillStyle = 'rgba(120,180,255,.14)';
  c.fillRect(0, HUD.h - 1, W, 1);

  // Rival side
  drawShieldIcon(c, 96, 48, 17, 'red');
  c.fillStyle = '#ffc1c8';
  c.font = font(9, 900);
  c.textAlign = 'left';
  c.textBaseline = 'middle';
  c.fillText('RIVAL', 121, 35);
  for (let i = 0; i < 3; i++) drawCrownPip(c, 124 + i * 19, 59, 7, i < red);

  // Player side
  drawShieldIcon(c, 624, 48, 17, 'blue');
  c.fillStyle = '#b9dcff';
  c.font = font(9, 900);
  c.textAlign = 'right';
  c.fillText('YOU', 599, 35);
  for (let i = 0; i < 3; i++) drawCrownPip(c, 596 - i * 19, 59, 7, i < blue);

  // Pause / sound buttons
  c.save();
  c.fillStyle = 'rgba(255,255,255,.06)';
  c.strokeStyle = 'rgba(160,200,255,.18)';
  c.lineWidth = 1;
  c.beginPath(); c.arc(42, 47, 21, 0, Math.PI * 2); c.fill(); c.stroke();
  c.beginPath(); c.arc(678, 47, 21, 0, Math.PI * 2); c.fill(); c.stroke();
  c.restore();
  drawPauseIcon(c, 42, 47, 12, '#dce9fb');
  drawSoundIcon(c, 678, 47, 11, g.sound.enabled, '#dce9fb');

  // Timer
  const danger = g.state === 'playing' && g.timeLeft <= 10;
  const pulse = danger ? 1 + Math.sin(g.time * 12) * 0.04 : 1;
  c.save();
  c.translate(360, 46);
  c.scale(pulse, pulse);
  fillRoundRect(c, -68, -29, 136, 58, 17, 'rgba(8,16,29,.88)');
  c.strokeStyle = danger ? 'rgba(255,110,120,.7)' : 'rgba(160,200,255,.25)';
  c.lineWidth = 1.5;
  roundRectPath(c, -68, -29, 136, 58, 17);
  c.stroke();
  c.fillStyle = danger ? '#ff9aa4' : '#f4f8ff';
  c.font = font(29, 900);
  c.textAlign = 'center';
  c.textBaseline = 'middle';
  c.fillText(formatTime(g.timeLeft), 0, 0);
  c.restore();

  let phase = '';
  let phaseColor = '#c693ff';
  if (g.overtime) { phase = 'OVERTIME'; phaseColor = '#ff9aa4'; }
  else if (g.state === 'playing' && g.timeLeft <= 60) phase = 'DOUBLE ELIXIR';
  else if (g.state === 'countdown') phase = 'GET READY';
  if (phase) {
    c.fillStyle = phaseColor;
    c.font = font(8.5, 900);
    c.textAlign = 'center';
    c.textBaseline = 'middle';
    c.fillText(phase, 360, 84);
  }

  drawHand(g, c);
}

function drawHand(g, c) {
  // Bottom panel
  const bottom = c.createLinearGradient(0, 1008, 0, H);
  bottom.addColorStop(0, 'rgba(7,14,25,0)');
  bottom.addColorStop(0.22, 'rgba(7,14,25,.9)');
  bottom.addColorStop(1, 'rgba(5,10,18,1)');
  c.fillStyle = bottom;
  c.fillRect(0, 1008, W, H - 1008);
  c.fillStyle = 'rgba(140,190,255,.12)';
  c.fillRect(20, 1018, W - 40, 1);

  const deck = g.playerDeck;

  // Elixir bar
  fillRoundRect(c, ELIXIR.x, ELIXIR.y, ELIXIR.w, ELIXIR.h, 13, 'rgba(11,22,38,.9)');
  const pct = clamp(deck.elixir / 10, 0, 1);
  c.save();
  roundRectPath(c, ELIXIR.x, ELIXIR.y, ELIXIR.w, ELIXIR.h, 13);
  c.clip();
  const fillGrad = c.createLinearGradient(ELIXIR.x, 0, ELIXIR.x + ELIXIR.w, 0);
  fillGrad.addColorStop(0, '#7a2ad6');
  fillGrad.addColorStop(0.6, '#b44dff');
  fillGrad.addColorStop(1, '#e29bff');
  c.fillStyle = fillGrad;
  c.fillRect(ELIXIR.x, ELIXIR.y, ELIXIR.w * pct, ELIXIR.h);
  c.fillStyle = 'rgba(255,255,255,.28)';
  c.fillRect(ELIXIR.x, ELIXIR.y, ELIXIR.w * pct, 7);
  c.strokeStyle = 'rgba(5,10,20,.4)';
  c.lineWidth = 1.5;
  for (let i = 1; i < 10; i++) {
    const x = ELIXIR.x + (ELIXIR.w / 10) * i;
    c.beginPath(); c.moveTo(x, ELIXIR.y); c.lineTo(x, ELIXIR.y + ELIXIR.h); c.stroke();
  }
  c.restore();
  roundRectPath(c, ELIXIR.x, ELIXIR.y, ELIXIR.w, ELIXIR.h, 13);
  c.strokeStyle = 'rgba(200,150,255,.28)';
  c.lineWidth = 1.5;
  c.stroke();

  // Elixir number
  c.save();
  c.beginPath(); c.arc(668, 1033, 17, 0, Math.PI * 2);
  const orb = c.createRadialGradient(662, 1026, 2, 668, 1033, 20);
  orb.addColorStop(0, '#3a1a5e');
  orb.addColorStop(1, '#170a28');
  c.fillStyle = orb;
  c.fill();
  c.strokeStyle = 'rgba(190,120,255,.55)';
  c.lineWidth = 1.5;
  c.stroke();
  c.fillStyle = '#f0d8ff';
  c.font = font(17, 900);
  c.textAlign = 'center';
  c.textBaseline = 'middle';
  c.fillText(String(Math.floor(deck.elixir)), 668, 1034);
  c.restore();

  // Cards
  for (let i = 0; i < 4; i++) {
    const id = deck.hand[i];
    if (!id) continue;
    const card = CARDS[id];
    const r = g.cardRect(i);
    let shake = 0;
    if (g.denied && g.denied.i === i) shake = Math.sin(g.denied.t * 75) * 5;
    drawCardFace(c, card, r.x, r.y, r.w, r.h, {
      selected: g.selected === i,
      affordable: deck.elixir + 0.001 >= card.cost,
      shake,
    });
  }

  // Next card
  const nextId = deck.queue[0];
  if (nextId) {
    c.fillStyle = 'rgba(160,185,215,.55)';
    c.font = font(7.5, 800);
    c.textAlign = 'center';
    c.textBaseline = 'middle';
    c.fillText('NEXT', NEXT.x + NEXT.w / 2, 1054);
    drawMiniCard(c, CARDS[nextId], NEXT.x, NEXT.y, NEXT.w, NEXT.h);
  }

  // Full-bar sparkle
  if (deck.elixir >= 9.98) {
    c.save();
    c.globalAlpha = 0.35 + Math.sin(g.time * 5) * 0.15;
    c.fillStyle = '#f3e3ff';
    c.font = font(9, 900);
    c.textAlign = 'right';
    c.textBaseline = 'middle';
    c.fillText('ELIXIR FULL', ELIXIR.x + ELIXIR.w - 12, ELIXIR.y + 13);
    c.restore();
  }
}

function drawHints(g, c) {
  if (g.state !== 'playing' || g.finishing) return;
  let text = '';
  let color = '#dce9fb';
  if (g.selected !== null) {
    const card = CARDS[g.playerDeck.hand[g.selected]];
    if (card) {
      const overArena = g.pointer.inside;
      const valid = overArena && g.canDeploy('blue', card, g.pointer.x, g.pointer.y);
      if (card.spell) text = overArena ? (valid ? 'Tap to cast' : 'Aim inside the arena') : 'Tap anywhere in the arena to cast';
      else text = overArena ? (valid ? 'Tap to deploy' : 'Can’t deploy there') : 'Tap your half of the arena';
      if (overArena && !valid) color = '#ff9aa4';
    }
  } else if (g.matchTime < 8) {
    text = 'Tap a card, then tap your half to deploy';
  }
  if (!text) return;
  c.save();
  c.font = font(11, 700);
  const w = c.measureText(text).width + 30;
  fillRoundRect(c, 360 - w / 2, 984, w, 27, 13, 'rgba(6,14,26,.82)');
  c.strokeStyle = 'rgba(150,195,255,.18)';
  c.lineWidth = 1;
  roundRectPath(c, 360 - w / 2, 984, w, 27, 13);
  c.stroke();
  c.fillStyle = color;
  c.textAlign = 'center';
  c.textBaseline = 'middle';
  c.fillText(text, 360, 998);
  c.restore();
}

function drawCountdown(g, c) {
  c.save();
  c.fillStyle = 'rgba(4,10,18,.38)';
  c.beginPath();
  roundRectPath(c, ARENA.x + 2, ARENA.y + 2, ARENA.w - 4, ARENA.h - 4, ARENA.r);
  c.fill();
  c.restore();

  const showClash = g.countdown <= 0.4;
  const n = Math.max(1, Math.ceil(g.countdown - 0.4));
  const text = showClash ? 'CLASH!' : String(n);

  c.save();
  c.translate(360, 520);
  const pop = showClash ? 1 + (0.4 - g.countdown) * 0.3 : 1;
  c.scale(pop, pop);
  c.textAlign = 'center';
  c.textBaseline = 'middle';
  c.font = font(showClash ? 82 : 116, 900);
  c.lineWidth = 14;
  c.strokeStyle = 'rgba(5,12,22,.75)';
  c.strokeText(text, 0, 0);
  const grad = c.createLinearGradient(0, -60, 0, 60);
  grad.addColorStop(0, '#fff6d8');
  grad.addColorStop(0.5, '#ffd45e');
  grad.addColorStop(1, '#e59c12');
  c.fillStyle = grad;
  c.fillText(text, 0, 0);
  c.restore();

  if (!showClash) {
    c.save();
    c.fillStyle = 'rgba(220,233,251,.72)';
    c.font = font(13, 800);
    c.textAlign = 'center';
    c.textBaseline = 'middle';
    c.fillText('DEFEND YOUR CROWNS', 360, 600);
    c.restore();
  }

  // Countdown ring
  const frac = Math.max(0, Math.min(1, (g.countdown - 0.4) % 1));
  c.save();
  c.strokeStyle = 'rgba(255,212,94,.4)';
  c.lineWidth = 4;
  c.beginPath();
  c.arc(360, 520, 112, -Math.PI / 2, -Math.PI / 2 + Math.PI * 2 * (1 - frac));
  c.stroke();
  c.restore();
}

function drawClash(g, c) {
  const a = clamp(g.clashFlash, 0, 1);
  c.save();
  c.globalAlpha = a;
  c.translate(360, 500);
  c.scale(1 + (1 - a) * 0.25, 1 + (1 - a) * 0.25);
  c.textAlign = 'center';
  c.textBaseline = 'middle';
  c.font = font(86, 900);
  c.lineWidth = 12;
  c.strokeStyle = 'rgba(5,12,22,.7)';
  c.strokeText('CLASH!', 0, 0);
  const grad = c.createLinearGradient(0, -50, 0, 50);
  grad.addColorStop(0, '#fff6d8');
  grad.addColorStop(0.55, '#ffd45e');
  grad.addColorStop(1, '#e59c12');
  c.fillStyle = grad;
  c.fillText('CLASH!', 0, 0);
  c.restore();
}

function drawBanner(g, c) {
  const b = g.banner;
  const t = b.t / b.dur;
  const appear = clamp(b.t / 0.22, 0, 1);
  const fade = t > 0.75 ? 1 - (t - 0.75) / 0.25 : 1;
  const scale = 0.85 + appear * 0.15;
  c.save();
  c.globalAlpha = clamp(fade, 0, 1) * clamp(appear, 0, 1);
  c.translate(360, 455);
  c.scale(scale, scale);
  const w = 390;
  fillRoundRect(c, -w / 2, -46, w, 92, 18, 'rgba(6,13,24,.88)');
  c.strokeStyle = b.color;
  c.lineWidth = 2;
  roundRectPath(c, -w / 2, -46, w, 92, 18);
  c.stroke();
  c.fillStyle = b.color;
  c.font = font(25, 900);
  c.textAlign = 'center';
  c.textBaseline = 'middle';
  c.fillText(b.text, 0, -13);
  c.fillStyle = 'rgba(225,238,255,.8)';
  c.font = font(11.5, 700);
  c.fillText(b.sub, 0, 17);
  c.restore();
}

