input.content:
import { createRequire } from 'node:module';
import { mkdirSync } from 'node:fs';
const require = createRequire(process.env.HOME + '/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');

const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox'] });
const errors = [];
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.waitForTimeout(600);
await page.screenshot({ path: out + '/mobile-menu.png' });
await page.tap('#play-btn');
await page.waitForTimeout(4500);

const box = await page.locator('#game').boundingBox();
const tapAt = async (gx, gy) => {
  const x = box.x + (gx / 720) * box.width;
  const y = box.y + (gy / 1280) * box.height;
  await page.touchscreen.tap(x, y);
};

const state = await page.evaluate(() => ({
  hand: window.__miniClash.playerDeck.hand,
  elixir: window.__miniClash.playerDeck.elixir,
  state: window.__miniClash.state,
}));
console.log('start', state);

// Pick the first troop in hand and deploy it.
const idx = state.hand.findIndex((id) => !['fireball', 'arrows'].includes(id));
await tapAt(95 + idx * 156, 1158);
await page.waitForTimeout(200);
await page.screenshot({ path: out + '/mobile-selected.png' });
await tapAt(300, 720);
await page.waitForTimeout(500);
await page.screenshot({ path: out + '/mobile-deploy.png' });
console.log('after tap deploy', await page.evaluate(() => ({ units: window.__miniClash.units.length, elixir: window.__miniClash.playerDeck.elixir, selected: window.__miniClash.selected })));

// Stress-simulate two minutes of match with auto-play on the player side.
const sim = await page.evaluate(() => {
  const g = window.__miniClash;
  const spells = ['fireball', 'arrows'];
  let plays = 0;
  for (let i = 0; i < 30 * 130; i++) {
    if (i % 42 === 0) {
      const idx = g.playerDeck.hand.findIndex((id) => !spells.includes(id) && g.canAfford(g.playerDeck.hand.indexOf(id)));
      for (let k = 0; k < g.playerDeck.hand.length; k++) {
        const id = g.playerDeck.hand[k];
        if (!spells.includes(id) && g.canAfford(k)) {
          const lane = Math.random() < 0.5 ? 190 : 530;
          if (g.playCard('blue', k, lane + (Math.random() * 60 - 30), 700 + Math.random() * 120)) plays++;
          break;
        }
      }
    }
    g.update(1 / 30);
    if (g.state === 'ended') break;
  }
  return {
    plays,
    state: g.state,
    timeLeft: g.timeLeft,
    overtime: g.overtime,
    crowns: [g.crowns('blue'), g.crowns('red')],
    units: g.units.length,
    towers: g.towers.map((t) => ({ team: t.team, king: t.king, hp: Math.round(t.hp), alive: t.alive })),
    result: g.result,
  };
});
console.log('sim', sim);
await page.waitForTimeout(1200);
await page.screenshot({ path: out + '/mobile-late.png' });

// Force a dramatic tower fall and check the end screen.
const forced = await page.evaluate(() => {
  const g = window.__miniClash;
  if (g.state === 'ended') { g.startRound(); g.countdown = 0; g.state = 'playing'; }
  const king = g.towers.find((t) => t.team === 'red' && t.king);
  g.applyDamage(king, 99999, 'blue');
  return { state: g.state, finishing: g.finishing, crowns: [g.crowns('blue'), g.crowns('red')] };
});
console.log('forced king', forced);
await page.waitForTimeout(2200);
await page.screenshot({ path: out + '/mobile-end.png' });
console.log('end panel visible', await page.locator('#end-panel').isVisible().catch(() => false));

console.log('errors:', errors.length ? errors : 'none');
await browser.close();

