import { createRequire } from 'node:module';
import { mkdirSync } from 'node:fs';
const require = createRequire(process.env.HOME + '/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox'] });
const errors = [];
const page = await browser.newPage({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1 });
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.waitForTimeout(500);
await page.screenshot({ path: out + '/desktop-menu.png' });
await page.click('#play-btn');
await page.waitForTimeout(3900);

const box = await page.locator('#game').boundingBox();
const mouseAt = async (gx, gy) => {
  const x = box.x + (gx / 720) * box.width;
  const y = box.y + (gy / 1280) * box.height;
  await page.mouse.move(x, y);
  return { x, y };
};
const clickAt = async (gx, gy) => {
  const p = await mouseAt(gx, gy);
  await page.mouse.click(p.x, p.y);
};

// Drag the first troop card onto the left lane.
let hand = await page.evaluate(() => window.__miniClash.playerDeck.hand);
let idx = hand.findIndex((id) => !['fireball', 'arrows'].includes(id));
const card = await mouseAt(95 + idx * 156, 1158);
await page.mouse.move(card.x, card.y);
await page.mouse.down();
await mouseAt(300, 700);
await page.waitForTimeout(120);
await page.screenshot({ path: out + '/desktop-drag.png' });
await page.mouse.up();
await page.waitForTimeout(1600);
await page.screenshot({ path: out + '/desktop-fight.png' });
console.log('drag deploy', await page.evaluate(() => ({ units: window.__miniClash.units.length, cards: window.__miniClash.stats.cardsPlayed })));

// Set up a juicy fireball target and cast it.
const spell = await page.evaluate(() => {
  const g = window.__miniClash;
  g.playerDeck.hand[0] = 'fireball';
  g.playerDeck.elixir = 10;
  // Put a cluster of red troops in the open.
  const card = { id: 'goblins', hp: 190, maxHp: 190, radius: 10, speed: 96, hit: 0.7, range: 18, dmg: 38, aggro: 115, targets: 'ground', kind: 'melee', count: 3 };
  g.spawnTroop('red', card, 380, 420);
  return { hand: g.playerDeck.hand, units: g.units.length };
});
console.log('spell setup', spell);
await clickAt(95, 1158);
await page.waitForTimeout(150);
const p = await mouseAt(380, 420);
await page.mouse.click(p.x, p.y);
await page.waitForTimeout(220);
await page.screenshot({ path: out + '/desktop-fireball-incoming.png' });
await page.waitForTimeout(500);
await page.screenshot({ path: out + '/desktop-fireball-boom.png' });
await page.waitForTimeout(400);

// Test overtime: tie at zero.
await page.evaluate(() => {
  const g = window.__miniClash;
  g.timeLeft = 0.02;
  g.overtime = false;
  g.playerDeck.elixir = 4;
});
await page.waitForTimeout(700);
await page.screenshot({ path: out + '/desktop-overtime.png' });
console.log('overtime', await page.evaluate(() => ({ overtime: window.__miniClash.overtime, timeLeft: window.__miniClash.timeLeft, banner: window.__miniClash.banner?.text })));

// Test pause panel.
await page.evaluate(() => { window.__miniClash.overtime = false; window.__miniClash.timeLeft = 90; });
await page.evaluate(() => window.__miniClash.pause());
await page.waitForTimeout(500);
await page.screenshot({ path: out + '/desktop-pause.png' });
console.log('pause panel', await page.locator('#pause-panel').isVisible());
await page.click('#resume-btn');
await page.waitForTimeout(300);

console.log('errors:', errors.length ? errors : 'none');
await browser.close();

