import { createRequire } from 'node:module';
const require = createRequire(process.env.HOME + '/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox'] });
const errors = [];
const page = await browser.newPage({ viewport: { width: 720, height: 1280 }, deviceScaleFactor: 1 });
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.click('#play-btn');
await page.waitForTimeout(700);
await page.screenshot({ path: out + '/countdown.png' });
await page.waitForTimeout(3400);

await page.evaluate(() => {
  const g = window.__miniClash;
  g.playerDeck.hand[0] = 'fireball';
  g.playerDeck.elixir = 10;
  const card = { id: 'goblins', hp: 190, maxHp: 190, radius: 10, speed: 96, hit: 0.7, range: 18, dmg: 38, aggro: 115, targets: 'ground', kind: 'melee', count: 3 };
  g.spawnTroop('red', card, 300, 430);
  g.spawnTroop('red', card, 330, 455);
});
await page.mouse.click(95, 1158);
await page.waitForTimeout(100);
await page.mouse.click(315, 442);
await page.waitForTimeout(160);
await page.screenshot({ path: out + '/fireball-travel.png' });
await page.waitForTimeout(420);
await page.screenshot({ path: out + '/fireball-impact.png' });
await page.waitForTimeout(700);
await page.screenshot({ path: out + '/fireball-after.png' });

// Destroy a princess tower and capture the fireworks.
await page.evaluate(() => {
  const g = window.__miniClash;
  const t = g.towers.find((t) => t.team === 'red' && !t.king && t.x < 360);
  g.applyDamage(t, 99999, 'blue');
});
await page.waitForTimeout(280);
await page.screenshot({ path: out + '/tower-down.png' });
await page.waitForTimeout(1500);
await page.screenshot({ path: out + '/tower-rubble.png' });

// Defeat screen.
await page.evaluate(() => {
  const g = window.__miniClash;
  const king = g.towers.find((t) => t.team === 'blue' && t.king);
  g.applyDamage(king, 99999, 'red');
});
await page.waitForTimeout(2200);
await page.screenshot({ path: out + '/defeat.png' });
console.log('end visible', await page.locator('#end-panel').isVisible());
console.log('errors:', errors.length ? errors : 'none');
await browser.close();

